/* tables4.js — 50 готовых завязок и ваншотов для начинающего Мастера: TABLES_EXTRA.oneshot=[{n,lvl,hook,scenes[],twist,reward}]. См. schema.md */
(function(){const T=window.TABLES_EXTRA=window.TABLES_EXTRA||{};T.oneshot=(T.oneshot||[]).concat([{"n": "Мельница, которая мелет ночью", "lvl": "1–2", "hook": "Мельник просит выяснить, кто по ночам запускает его мельницу: утром мешки полны муки, а зерно не тронуто.", "scenes": ["Засада у мельницы ночью", "Следы маленьких ног к ручью", "Логово под плотиной"], "twist": "Муку мелют домовые-брауни, которых мельник обидел; они хотят извинений и миску сливок", "reward": "30 зм, бесплатный хлеб, брауни-союзник"}, {"n": "Пропавший колокол", "lvl": "1–3", "hook": "С деревенской часовни украли колокол, и теперь по ночам к околице подходят волки.", "scenes": ["Расспросы в деревне", "След телеги в лес", "Лагерь гоблинов с колоколом"], "twist": "Гоблины украли его, чтобы звонить и отгонять от своего лагеря нечто страшнее волков", "reward": "50 зм, благодарность старосты, информация о чудовище"}, {"n": "Свадьба с подвохом", "lvl": "2–4", "hook": "Героев нанимают охранять свадьбу дочери купца: жених получил анонимную угрозу.", "scenes": ["Подготовка и знакомство с гостями", "Отравленное вино", "Погоня за подозреваемым"], "twist": "Угрозу написала сама невеста, чтобы сорвать свадьбу с нелюбимым", "reward": "100 зм или помощь невесте сбежать"}, {"n": "Голодный мост", "lvl": "1–3", "hook": "Старый каменный мост «съедает» путников: заходят на него, а на другой берег не выходят.", "scenes": ["Осмотр моста", "Тролль под мостом? Нет — мимик-мост", "Спасение пленников из «желудка»"], "twist": "Мост — гигантский мимик, которого подкармливает сборщик пошлины", "reward": "Вещи пропавших, 80 зм"}, {"n": "Ярмарочный обман", "lvl": "1–2", "hook": "На ярмарке гадалка предсказала героям гибель «до заката», и тут же начинаются странные покушения.", "scenes": ["Ярмарочные игры", "Покушения: падающая бочка, бешеный бык", "Разоблачение в шатре"], "twist": "Гадалка — мошенница, а «покушения» подстроены, чтобы продать героям «защитный амулет»", "reward": "Деньги гадалки, репутация"}, {"n": "Одна ночь в склепе", "lvl": "2–4", "hook": "Наследник предлагает 200 зм тому, кто проведёт ночь в фамильном склепе и докажет, что призраков нет.", "scenes": ["Вход и ловушки склепа", "Призрак предка", "Встреча с живым грабителем"], "twist": "Призрак настоящий и хочет назвать настоящего убийцу — самого наследника", "reward": "200 зм или фамильный меч призрака"}, {"n": "Кузнец без огня", "lvl": "1–3", "hook": "В кузнице погас горн и не разжигается ничем: мастер говорит, что дух огня ушёл.", "scenes": ["Поиски в кузнице", "Пещера огненных жуков", "Переговоры с саламандрой"], "twist": "Духа огня обидел подмастерье, вылив в горн святую воду", "reward": "Оружие +1 от кузнеца"}, {"n": "Чужие воспоминания", "lvl": "3–5", "hook": "Горожане просыпаются с чужими воспоминаниями: пекарь помнит, как был капитаном, а стражник — как пёк хлеб.", "scenes": ["Опрос «перепутанных»", "Странный торговец снами", "Битва в мире снов"], "twist": "Торговец ворует сны для заказчика и перепутал склянки", "reward": "Склянка с воспоминанием (одно заклинание 2 круга)"}, {"n": "Караван через перевал", "lvl": "2–4", "hook": "Купец нанимает охрану для каравана через горный перевал перед первым снегом.", "scenes": ["Лавина на тропе", "Нападение снежных волков", "Укрытие в заброшенном форте"], "twist": "В одной повозке спрятан похищенный ребёнок знатной семьи", "reward": "150 зм, награда семьи"}, {"n": "Сорока-воровка", "lvl": "1", "hook": "У всей деревни пропадают блестящие вещи, включая обручальное кольцо старосты.", "scenes": ["Ловля сорок", "Гнездо на старом дубе", "Хозяин сорок — юный чародей"], "twist": "Ребёнок-чародей приручил сорок и не знает, что это плохо", "reward": "Возврат вещей, 20 зм, благодарный ученик"}, {"n": "Танцующий лес", "lvl": "3–5", "hook": "Деревья в лесу каждую ночь меняют место, и путники выходят не туда, куда шли.", "scenes": ["Блуждание в лесу", "Встреча с дриадой", "Круг фей"], "twist": "Феи празднуют свадьбу и не хотят гостей; за приглашение придётся заплатить", "reward": "Благословение фей, дорога через лес"}, {"n": "Последний рейс «Чайки»", "lvl": "3–5", "hook": "Корабль-призрак «Чайка» каждый год возвращается в порт в день своей гибели.", "scenes": ["Ожидание на причале", "Абордаж призрака", "Каюта капитана"], "twist": "Команда не знает, что мертва, и ищет предателя, открывшего пробоину", "reward": "Сундук капитана, 300 зм"}, {"n": "Учёный в беде", "lvl": "2–4", "hook": "Маг из башни не отвечает неделю; его сестра просит проверить.", "scenes": ["Башня с ловушками", "Взбесившиеся конструкты", "Маг, превращённый в кота"], "twist": "Ученик мага сбежал, неудачно сотворив «Превращение»", "reward": "Свиток на выбор, 150 зм"}, {"n": "Пир у великана", "lvl": "5–7", "hook": "Холмовой великан пригласил всю деревню на пир; отказаться нельзя.", "scenes": ["Дорога к великану", "Пир и игры силы", "Побег или переговоры"], "twist": "Великан одинок и не хочет есть гостей — его повариха-ведьма хочет", "reward": "Дружба великана, мешок золота 400 зм"}, {"n": "Источник молодости", "lvl": "4–6", "hook": "В горной деревне никто не стареет; путник просит найти его пропавшую дочь, ушедшую туда.", "scenes": ["Прибытие в идиллию", "Тайны жителей", "Святилище источника"], "twist": "Источник крадёт годы у гостей, чтобы питать местных", "reward": "Свобода дочери, флакон источника (зелье лечения высшее)"}, {"n": "Король крыс", "lvl": "1–3", "hook": "Под городом крысы собираются в армию и уже нападают на склады.", "scenes": ["Канализация", "Крысолюды", "Трон из хвостов"], "twist": "Королём правит отчаявшийся алхимик, ставший крысолюдом", "reward": "100 зм от гильдии торговцев"}, {"n": "Вор в храме", "lvl": "2–3", "hook": "Из храма пропала реликвия, и подозревают новичка-послушника.", "scenes": ["Осмотр храма", "Допрос служителей", "Ночная слежка"], "twist": "Реликвию взял сам настоятель, чтобы продать и покрыть долги храма", "reward": "Благодарность, бесплатное лечение"}, {"n": "Дорога без конца", "lvl": "3–5", "hook": "Дорога между двумя сёлами стала бесконечной: путники идут днями и возвращаются.", "scenes": ["Первая попытка пройти", "Странные указатели", "Логово духа перекрёстка"], "twist": "Дух дороги заключён в межевой камень, который сдвинули", "reward": "Благословение путника (+3 м скорости на неделю)"}, {"n": "Гнездо виверны", "lvl": "5–7", "hook": "Виверна утаскивает скот; лорд обещает награду за её голову.", "scenes": ["Следопытство в горах", "Подъём к гнезду", "Схватка с виверной"], "twist": "В гнезде — яйца, которые дороже награды; браконьер тоже идёт за ними", "reward": "500 зм или яйцо"}, {"n": "Тень на маскараде", "lvl": "4–6", "hook": "На маскараде в поместье должен быть убит гость; известно только, что убийца — в маске ворона.", "scenes": ["Бал", "Пять масок ворона", "Погоня по крышам"], "twist": "Убийца — сама жертва, инсценирующая смерть, чтобы исчезнуть", "reward": "300 зм, связи в высшем обществе"}, {"n": "Затопленная часовня", "lvl": "2–4", "hook": "Озеро обмелело, и показалась крыша затопленной часовни, о которой ходят легенды.", "scenes": ["Спуск в часовню", "Утопленники", "Подводный зал"], "twist": "Часовня — тюрьма водяного духа, и героям решать, выпустить ли его", "reward": "Сокровища часовни 200 зм, магический предмет"}, {"n": "Испытание оруженосца", "lvl": "1–2", "hook": "Юный оруженосец просит помочь ему пройти рыцарское испытание — убить «дракона».", "scenes": ["Подготовка", "Пещера «дракона»", "Встреча с ним"], "twist": "«Дракон» — псевдодракон, которого оруженосцу жалко убивать", "reward": "Дружба псевдодракона, 50 зм"}, {"n": "Ночь длинных ножей", "lvl": "5–8", "hook": "Гильдия воров раскололась, и на улицах война; обе стороны хотят нанять героев.", "scenes": ["Встреча с обеими сторонами", "Засада", "Решающий бой в катакомбах"], "twist": "Раскол устроил городской капитан стражи, чтобы уничтожить обе стороны", "reward": "Покровительство одной из сторон"}, {"n": "Немые колокола", "lvl": "3–5", "hook": "В городе перестали звучать звуки после заката: никто не может говорить или звонить.", "scenes": ["Расследование в тишине", "Культ безмолвия", "Ритуал в соборе"], "twist": "Культисты хотят призвать существо, которое приходит только в тишину", "reward": "300 зм от городского совета"}, {"n": "Сундук мертвеца", "lvl": "2–4", "hook": "Героям достаётся карта сокровищ в наследство от незнакомого им дядюшки.", "scenes": ["Поиски по подсказкам", "Соперники-кладоискатели", "Пещера на острове"], "twist": "Дядюшка жив и устроил всё, чтобы проверить наследников", "reward": "Настоящее наследство 400 зм"}, {"n": "Зима не уходит", "lvl": "4–6", "hook": "Весна не наступает уже месяц; посреди долины стоит ледяная башня.", "scenes": ["Замёрзшая долина", "Ледяные элементали", "Башня зимней девы"], "twist": "Зимняя фея держит весну в плену из-за разбитого сердца", "reward": "Благословение весны, 300 зм"}, {"n": "Похищенный жених", "lvl": "1–3", "hook": "Накануне свадьбы жениха утащили в болото; невеста просит его вернуть.", "scenes": ["Болотные тропы", "Хижина болотной ведьмы", "Обмен"], "twist": "Жених сам заключил сделку с ведьмой и не хочет домой", "reward": "60 зм, зелье от ведьмы"}, {"n": "Ярмарка уродцев", "lvl": "3–5", "hook": "Бродячий цирк показывает «чудовищ», но одно из них просит о помощи на чистом общем языке.", "scenes": ["Представление", "Ночной визит за кулисы", "Побег с пленниками"], "twist": "Хозяин цирка держит в клетках проклятых людей", "reward": "Благодарность освобождённых, 150 зм"}, {"n": "Камень в почках горы", "lvl": "3–5", "hook": "Дварфы просят очистить шахту от «камней, которые ходят».", "scenes": ["Шахта", "Гаргульи и земляные элементали", "Сердце горы"], "twist": "Дварфы разбудили гору, добыв её сердце-самоцвет", "reward": "500 зм, скидка у кузнецов клана"}, {"n": "Ведьма с соседней улицы", "lvl": "1–2", "hook": "Соседи уверены, что старушка на окраине — ведьма, и требуют её изгнать.", "scenes": ["Слухи", "Визит к старушке", "Настоящий виновник порчи"], "twist": "Старушка — знахарка, а порчу наводит завистливый торговец", "reward": "Благодарность, зелья лечения"}, {"n": "Чёрная карета", "lvl": "4–6", "hook": "По ночам по городу ездит чёрная карета без кучера и увозит людей.", "scenes": ["Ночная засада", "Погоня", "Особняк вампира"], "twist": "Карета — приглашение на бал вампиров, куда можно попасть только так", "reward": "Освобождённые пленники, 400 зм"}, {"n": "Голос из колодца", "lvl": "1–3", "hook": "Из старого колодца доносится голос, обещающий исполнить желание.", "scenes": ["Колодец", "Спуск", "Встреча с исполнителем"], "twist": "В колодце живёт голодный мимик-оборотень, имитирующий голоса", "reward": "Монеты на дне колодца 70 зм"}, {"n": "Стрела в небо", "lvl": "2–4", "hook": "Турнир лучников, приз — серебряная стрела; за ним охотится кто-то ещё.", "scenes": ["Турнир", "Ночная кража", "Разоблачение"], "twist": "Серебряная стрела — ключ к древнему склепу", "reward": "Стрела (+1), вход в склеп"}, {"n": "Сад каменных статуй", "lvl": "4–6", "hook": "В саду богатого вдовца всё больше статуй, а в городе пропадают люди.", "scenes": ["Визит в поместье", "Странные статуи", "Логово медузы"], "twist": "Медуза — его жена, которую он прячет и любит", "reward": "Освобождение статуй, 300 зм"}, {"n": "Свиток, который читает себя", "lvl": "3–5", "hook": "Купленный на рынке свиток каждую ночь произносит заклинания сам.", "scenes": ["Странные явления в таверне", "Поиск продавца", "Башня автора"], "twist": "В свиток заключён дух его создателя", "reward": "Свиток с заклинанием 3 круга"}, {"n": "Бой за мост", "lvl": "2–4", "hook": "Две деревни спорят о мосте и вот-вот начнут драку; обе зовут героев.", "scenes": ["Переговоры", "Саботаж ночью", "Тролль под мостом"], "twist": "Ссору раздувает тролль, чтобы питаться погибшими", "reward": "Благодарность обеих деревень, 100 зм"}, {"n": "Остров за туманом", "lvl": "5–7", "hook": "Раз в десять лет из тумана появляется остров; рыбаки говорят, что там клад.", "scenes": ["Плавание", "Остров", "Храм в центре"], "twist": "Остров — панцирь спящей гигантской черепахи", "reward": "Сокровища храма 600 зм"}, {"n": "Сонная деревня", "lvl": "2–4", "hook": "Все жители деревни уснули и не просыпаются уже три дня.", "scenes": ["Спящие улицы", "Мак на полях", "Колдун в мельнице"], "twist": "Колдун ворует сны жителей, чтобы спастись от своих кошмаров", "reward": "Благодарность жителей, 150 зм"}, {"n": "Охота на оборотня", "lvl": "3–5", "hook": "Ночью в деревне растерзан скот, следы — огромного волка.", "scenes": ["Расследование", "Ночная засада", "Кто из жителей?"], "twist": "Оборотень — ребёнок, не понимающий проклятья; его можно излечить", "reward": "200 зм, «Снятие проклятья» от жреца"}, {"n": "Подменыш", "lvl": "1–3", "hook": "Мать уверена, что её младенца подменили феи.", "scenes": ["Проверки «ребёнка»", "Тропа в мир фей", "Торг с феями"], "twist": "Подмена действительно была, но настоящий ребёнок не хочет назад", "reward": "Дар фей"}, {"n": "Пять голов гидры", "lvl": "6–8", "hook": "Гидра поселилась в реке, а рыцари гибнут один за другим.", "scenes": ["Подготовка", "Болото", "Схватка с гидрой"], "twist": "Гидру подкармливает мэр, чтобы перекрыть торговлю соседей", "reward": "800 зм"}, {"n": "Мёртвые не лгут", "lvl": "3–5", "hook": "Убит богатый купец; некромант предлагает допросить труп.", "scenes": ["Место убийства", "Ритуал допроса", "Погоня"], "twist": "Труп называет убийцу — одного из героев под чарами", "reward": "Оправдание, 250 зм"}, {"n": "Лавка ненужных вещей", "lvl": "1–3", "hook": "Торговец продаёт магические предметы по смешным ценам, но покупатели исчезают.", "scenes": ["Покупка", "Слежка", "Подвал лавки"], "twist": "Каждый предмет — клетка для души покупателя", "reward": "Освобождённые души, предмет на выбор"}, {"n": "Пограничная застава", "lvl": "2–4", "hook": "Застава на границе не отвечает; отряд отправляют проверить.", "scenes": ["Пустая застава", "Следы борьбы", "Пещера орков"], "twist": "Солдаты дезертировали, а орки тут ни при чём", "reward": "Награда от командования 200 зм"}, {"n": "Кошачий король", "lvl": "1–2", "hook": "Кошки города собрались на крыше ратуши и не расходятся; мэр просит разобраться.", "scenes": ["Кошачье собрание", "Говорящий кот", "Похищенная корона"], "twist": "Кто-то украл корону кошачьего короля", "reward": "Дружба кошек: глаза и уши по всему городу"}, {"n": "Тайна мёртвого маяка", "lvl": "3–5", "hook": "Маяк погас, и корабли разбиваются о скалы; смотритель исчез.", "scenes": ["Маяк", "Пещера под скалой", "Мародёры"], "twist": "Смотритель в сговоре с мародёрами", "reward": "300 зм от гильдии мореходов"}, {"n": "Гостиница на перекрёстке", "lvl": "1–3", "hook": "В придорожной гостинице постояльцы по ночам видят одно и то же убийство.", "scenes": ["Ночь в гостинице", "Призрачное убийство", "Тайник под полом"], "twist": "Призрак ждёт, когда найдут его тело и письмо", "reward": "Письмо с картой клада"}, {"n": "Ключ от неба", "lvl": "6–8", "hook": "Маг просит доставить ключ к парящей в облаках башне.", "scenes": ["Подъём", "Облачные великаны", "Дверь башни"], "twist": "Ключ запирает, а не открывает: башня должна упасть на город врагов мага", "reward": "Выбор: награда мага или спасение города"}, {"n": "Детский крестовый поход", "lvl": "2–4", "hook": "Дети из трёх деревень ушли в лес за дудочником.", "scenes": ["Следы детей", "Дудочник", "Пещера фей"], "twist": "Дудочник уводит детей от чумы, о которой знает только он", "reward": "Благодарность, знание о чуме"}, {"n": "Последнее желание дракона", "lvl": "8–10", "hook": "Умирающий древний дракон зовёт героев и просит исполнить последнее желание.", "scenes": ["Логово", "Желание: защитить яйцо", "Охотники за сокровищами"], "twist": "Дракон хочет, чтобы его сокровище досталось новым хозяевам — героям", "reward": "Часть клада дракона"}]);})();

