const BLK={'холщовое':P.cloth,'красное':P.red,'синее':P.blue,'клетчатое':'check','меховое':'fur','полосатое':'stripe'};
const bedBase={'одинарная':{w:1,h:2},'двуспальная':{w:2,h:2},'под балдахином':{w:2,h:3},'соломенный тюфяк':{w:1,h:2},'походная койка':{w:1,h:2},'двухъярусная':{w:1,h:2}};
const blanket=(c,S,x,y,w,h,b,rnd)=>{c.save();rr(c,x,y,w,h,S*.06);c.clip();if(b==='check'){for(let i=0;i<w/(S*.15)+1;i++)for(let j=0;j<h/(S*.15)+1;j++){c.fillStyle=(i+j)%2?'#6e1e18':'#b8a070';c.fillRect(x+i*S*.15,y+j*S*.15,S*.15,S*.15)}c.fillStyle='rgba(30,40,80,.25)';for(let i=0;i<w/(S*.3);i++)c.fillRect(x+i*S*.3,y,S*.05,h)}else if(b==='fur'){c.fillStyle='#6a5236';c.fillRect(x,y,w,h);c.strokeStyle='rgba(30,20,10,.5)';c.lineWidth=S*.012;for(let i=0;i<w*h/(S*S)*120;i++){const px=x+rnd()*w,py=y+rnd()*h;c.beginPath();c.moveTo(px,py);c.lineTo(px+(rnd()-.5)*S*.06,py+S*.05);c.stroke()}c.strokeStyle='rgba(220,200,160,.25)';for(let i=0;i<w*h/(S*S)*60;i++){const px=x+rnd()*w,py=y+rnd()*h;c.beginPath();c.moveTo(px,py);c.lineTo(px+(rnd()-.5)*S*.06,py+S*.05);c.stroke()}}else if(b==='stripe'){for(let i=0;i<h/(S*.1);i++){c.fillStyle=i%3?'#c6b28a':'#1f3560';c.fillRect(x,y+i*S*.1,w,S*.1)}}else{c.fillStyle=lg(c,x,y,x+w,y+h,[b[3],b[1]]);c.fillRect(x,y,w,h);c.strokeStyle='rgba(0,0,0,.18)';c.lineWidth=S*.02;for(let i=0;i<4;i++){c.beginPath();c.moveTo(x+rnd()*w,y);c.quadraticCurveTo(x+rnd()*w,y+h/2,x+rnd()*w,y+h);c.stroke()}}c.restore();ink(c,S,.025);rr(c,x,y,w,h,S*.06);c.stroke();c.fillStyle='rgba(255,255,255,.18)';c.fillRect(x,y,w,S*.12)};
const pillow=(c,S,x,y,w)=>{rr(c,x,y,w,S*.28,S*.1);c.fillStyle=lg(c,x,y,x,y+S*.28,['#f0ead8','#c8bea0']);c.fill();ink(c,S,.02);c.stroke()};
for(const bb in bedBase)for(const bl in BLK){const B=bedBase[bb],b=BLK[bl];if(bb==='соломенный тюфяк'&&bl!=='холщовое'&&bl!=='клетчатое')continue;if(bb==='походная койка'&&!['холщовое','меховое','синее'].includes(bl))continue;
 M.add({id:'md1-bed-'+slug(bb)+'-'+slug(bl),n:'Кровать: '+bb+', одеяло '+bl,cat:'Мебель',th:bb==='походная койка'?['лагерь','казарма']:bb==='соломенный тюфяк'?['тюрьма','ферма','трущобы']:bb==='под балдахином'?['замок','эльфы']:bb==='двухъярусная'?['казарма','корабль']:['таверна','дом'],w:B.w,h:B.h,solid:true,layer:'object',v:['mat:wood|dwood|lwood'],
 draw:(c,S,p,rnd)=>{const pal=M.mat(p,'wood'),W=B.w*S,H=B.h*S;
  if(bb==='соломенный тюфяк'){shadow(c,S,()=>{rr(c,S*.1,S*.15,W-S*.2,H-S*.3,S*.15);c.fillStyle='#b8a060';c.fill()});c.strokeStyle='rgba(120,90,30,.7)';c.lineWidth=S*.012;for(let i=0;i<70;i++){const x=S*.15+rnd()*(W-S*.3),y=S*.2+rnd()*(H-S*.4);c.beginPath();c.moveTo(x,y);c.lineTo(x+(rnd()-.5)*S*.2,y+(rnd()-.5)*S*.1);c.stroke()}blanket(c,S,S*.15,H*.45,W-S*.3,H*.45,b,rnd);return}
  if(bb==='походная койка'){shadow(c,S,()=>{c.fillStyle=pal[1];c.fillRect(S*.18,S*.1,W-S*.36,H-S*.2)});c.fillStyle=pal[0];c.fillRect(S*.15,S*.1,S*.06,H-S*.2);c.fillRect(W-S*.21,S*.1,S*.06,H-S*.2);c.fillStyle='#8a7656';c.fillRect(S*.21,S*.12,W-S*.42,H-S*.24);ink(c,S,.02);c.strokeRect(S*.21,S*.12,W-S*.42,H-S*.24);blanket(c,S,S*.22,H*.4,W-S*.44,H*.5,b,rnd);return}
  const m=S*.07;shadow(c,S,()=>{c.fillStyle=pal[0];c.fillRect(m,m,W-2*m,H-2*m)});wood(c,S,m,m,W-2*m,S*.18,pal,rnd,'h',1);wood(c,S,m,H-m-S*.1,W-2*m,S*.1,pal,rnd,'h',1);rr(c,m+S*.05,m+S*.18,W-2*m-S*.1,H-2*m-S*.28,S*.05);c.fillStyle='#e8e0c8';c.fill();
  if(B.w===2){pillow(c,S,S*.2,S*.32,S*.72);pillow(c,S,S*1.08,S*.32,S*.72)}else pillow(c,S,S*.2,S*.32,S*.6);
  blanket(c,S,m+S*.03,H*(B.h===3?.33:.38),W-2*m-S*.06,H*(B.h===3?.55:.52),b,rnd);
  if(bb==='двухъярусная'){c.fillStyle='rgba(0,0,0,.3)';c.fillRect(m,H*.36,W-2*m,S*.04);c.fillStyle=pal[1];for(let i=0;i<5;i++)c.fillRect(W-m-S*.08,S*.3+i*S*.25,S*.08,S*.04)}
  if(bb==='под балдахином'){c.fillStyle=pal[0];[[m,m],[W-m-S*.14,m],[m,H-m-S*.14],[W-m-S*.14,H-m-S*.14]].forEach(q=>{c.fillRect(q[0],q[1],S*.14,S*.14);ink(c,S,.02);c.strokeRect(q[0],q[1],S*.14,S*.14)});c.save();c.globalAlpha=.35;c.fillStyle='#7a4f94';c.fillRect(m,m,W-2*m,S*.25);c.fillRect(m,m,S*.2,H-2*m);c.fillRect(W-m-S*.2,m,S*.2,H-2*m);c.restore();c.strokeStyle='rgba(122,79,148,.8)';c.lineWidth=S*.02;for(let i=0;i<8;i++){c.beginPath();c.moveTo(m+S*.03+i*S*.02,m);c.lineTo(m+S*.05+i*S*.02,H-m);c.stroke()}}
 }})}
