const shelfF=(content,len,dmg)=>(c,S,p,rnd)=>{const pal=M.mat(p,'dwood'),W=len*S;shadow(c,S,()=>{c.fillStyle=pal[0];c.fillRect(S*.05,S*.05,W-S*.1,S*.45)});wood(c,S,S*.05,S*.05,W-S*.1,S*.45,pal,rnd,'h',1);const x0=S*.1,x1=W-S*.1;let x=x0;
 if(content==='книги'){while(x<x1-S*.04){const bw=S*(.04+rnd()*.05);c.fillStyle=['#6e1e18','#1f3560','#2d4626','#5a3470','#7a5432','#3a3940','#9a7328'][rnd()*7|0];c.fillRect(x,S*.1+rnd()*S*.04,bw,S*.32);c.strokeStyle='rgba(0,0,0,.6)';c.lineWidth=S*.006;c.strokeRect(x,S*.1,bw,S*.34);if(rnd()<.3){c.fillStyle='#c49a3c';c.fillRect(x,S*.2,bw,S*.015)}x+=bw+S*.005;if(rnd()<.07)x+=S*.12}}
 else if(content==='зелья'){while(x<x1-S*.08){T.potion(c,S,x+S*.06,S*.27+(rnd()-.5)*S*.1,POT[rnd()*5|0]);x+=S*.12+rnd()*S*.05}}
 else if(content==='свитки'){while(x<x1-S*.08){for(let k=0;k<2;k++){c.fillStyle='#d9c79a';circ(c,x+S*.05,S*.18+k*S*.15,S*.05);c.fill();ink(c,S,.01);c.stroke();c.fillStyle='#8a7050';circ(c,x+S*.05,S*.18+k*S*.15,S*.015);c.fill()}x+=S*.11}}
 else if(content==='посуда'){while(x<x1-S*.1){T.plate(c,S,x+S*.1,S*.27,S*.1);x+=S*.2;if(rnd()<.5){T.mug(c,S,x,S*.27);x+=S*.12}}}
 else if(content==='черепа'){while(x<x1-S*.1){T.skull(c,S,x+S*.09,S*.27,.9);x+=S*.2}}
 else if(content==='банки'){while(x<x1-S*.1){circ(c,x+S*.07,S*.27,S*.065);c.fillStyle=['rgba(120,160,90,.8)','rgba(180,140,80,.8)','rgba(150,60,60,.8)'][rnd()*3|0];c.fill();ink(c,S,.015);c.stroke();c.fillStyle='rgba(240,230,200,.8)';blob(c,x+S*.07,S*.27,S*.03,rnd,6,.6);c.fill();x+=S*.15}}
 else if(content==='пустая'){c.fillStyle='rgba(200,190,170,.15)';for(let i=0;i<8;i++){circ(c,x0+rnd()*(x1-x0),S*.27,S*.03);c.fill()}c.strokeStyle='rgba(220,220,220,.35)';c.lineWidth=S*.005;c.beginPath();c.moveTo(x1,S*.08);c.quadraticCurveTo(x1-S*.1,S*.2,x1-S*.2,S*.1);c.stroke()}
 if(dmg){c.save();c.globalCompositeOperation='destination-out';poly(c,[[W*.6,0],[W*.75,S*.6],[W*.55,S*.6],[W*.5,0]]);c.fill();c.restore();c.fillStyle=pal[1];for(let i=0;i<4;i++){c.save();c.translate(W*(.5+rnd()*.3),S*(.6+rnd()*.3));c.rotate(rnd()*PI);c.fillRect(-S*.15,-S*.03,S*.3,S*.06);c.restore()}T.book(c,S,W*.65,S*.8,rnd()*3,'#1f3560');T.book(c,S,W*.45,S*.75,rnd()*3,'#6e1e18')}};
const SHC={'книги':['библиотека','башня мага','замок'],'зелья':['лаборатория','лавка'],'свитки':['библиотека','храм'],'посуда':['таверна','кухня','дом'],'черепа':['склеп','логово некроманта'],'банки':['лаборатория','кухня'],'пустая':['руины','подземелье']};
for(const ct in SHC)for(const L of [1,2,3])M.add({id:'md1-shelf-'+slug(ct)+'-'+L,n:'Стеллаж ('+ct+'), '+L+' кл.',cat:'Мебель',th:SHC[ct],w:L,h:1,solid:true,layer:'object',v:['mat:dwood|wood|lwood'],draw:shelfF(ct,L)});
