const barrelTop=(c,S,x,y,r,pal,rnd,lid)=>{shadow(c,S,()=>{circ(c,x,y,r);c.fillStyle=pal[1];c.fill()});c.save();circ(c,x,y,r);c.clip();wood(c,S,x-r,y-r,2*r,2*r,pal,rnd,'v',5);c.restore();circ(c,x,y,r);c.strokeStyle='#2b2d30';c.lineWidth=S*.05;c.stroke();ink(c,S,.02);circ(c,x,y,r+S*.025);c.stroke();circ(c,x,y,r*.82);c.strokeStyle='#45484d';c.lineWidth=S*.025;c.stroke();if(lid==='вода'){circ(c,x,y,r*.75);c.fillStyle=rg(c,x-r*.3,y-r*.3,0,r,['#4a8090','#0f2430']);c.fill()}else if(lid==='вино'){circ(c,x,y,r*.75);c.fillStyle=rg(c,x,y,0,r,['#6e1e2a','#2a0810']);c.fill()}else if(lid==='яблоки'){for(let i=0;i<8;i++){const a=rnd()*PI*2,d=rnd()*r*.55;circ(c,x+Math.cos(a)*d,y+Math.sin(a)*d,r*.2);c.fillStyle=rnd()<.7?'#a8281e':'#7a9a3a';c.fill();ink(c,S,.01);c.stroke()}}else if(lid==='рыба'){for(let i=0;i<5;i++){c.save();c.translate(x+(rnd()-.5)*r,y+(rnd()-.5)*r);c.rotate(rnd()*PI);ell(c,0,0,r*.4,r*.13);c.fillStyle='#8a9aa4';c.fill();ink(c,S,.01);c.stroke();c.restore()}}else if(lid==='порох'){c.fillStyle='#22170e';c.font=`bold ${r*.7}px serif`;c.textAlign='center';c.textBaseline='middle';c.fillText('☠',x,y)}else if(lid==='стрелы'){for(let i=0;i<9;i++){const a=rnd()*PI*2,d=rnd()*r*.55;c.fillStyle=['#e6e0d0','#952b22','#2d4626'][i%3];poly(c,[[x+Math.cos(a)*d,y+Math.sin(a)*d-S*.04],[x+Math.cos(a)*d+S*.03,y+Math.sin(a)*d+S*.03],[x+Math.cos(a)*d-S*.03,y+Math.sin(a)*d+S*.03]]);c.fill()}}else if(lid==='кран'){c.fillStyle='#9a7328';c.fillRect(x+r*.6,y-S*.03,r*.6,S*.06)}else{circ(c,x,y,S*.03);c.fillStyle='#2e1f14';c.fill()}};
