const chest=(c,S,x,y,w,h,pal,rnd,st)=>{shadow(c,S,()=>{rr(c,x,y,w,h,S*.06);c.fillStyle=pal[1];c.fill()});if(st==='open'||st==='gold'||st==='mimic'||st==='empty'){wood(c,S,x,y,w,h*.22,P.dwood,rnd,'h',1);wood(c,S,x,y+h*.22,w,h*.78,pal,rnd,'h',3);c.fillStyle=st==='empty'?'#2e1f14':'#3a2010';c.fillRect(x+S*.06,y+h*.3,w-S*.12,h*.62);if(st==='gold'){for(let i=0;i<30;i++){circ(c,x+S*.1+rnd()*(w-S*.2),y+h*.35+rnd()*h*.52,S*.035);c.fillStyle=['#d8b440','#f2da7a','#b08a1c'][i%3];c.fill()}T.gem(c,S,x+w*.3,y+h*.6,'#c02a2a');T.gem(c,S,x+w*.7,y+h*.7,'#2ac06a')}if(st==='mimic'){c.fillStyle='#8a1e2a';c.fillRect(x+S*.06,y+h*.3,w-S*.12,h*.62);c.fillStyle='#e8e0c8';for(let i=0;i<w/(S*.08);i++){poly(c,[[x+S*.06+i*S*.08,y+h*.3],[x+S*.1+i*S*.08,y+h*.45],[x+S*.14+i*S*.08,y+h*.3]]);c.fill();poly(c,[[x+S*.06+i*S*.08,y+h*.92],[x+S*.1+i*S*.08,y+h*.78],[x+S*.14+i*S*.08,y+h*.92]]);c.fill()}c.fillStyle='#c84a5a';ell(c,x+w/2,y+h*.62,w*.25,h*.1);c.fill()}}else{wood(c,S,x,y,w,h,pal,rnd,'h',3)}
 c.fillStyle=st==='rich'?'#c49a3c':'#2b2d30';[x+w*.2,x+w*.8-S*.06].forEach(bx=>{c.fillRect(bx,y,S*.06,h)});if(st!=='open'&&st!=='gold'&&st!=='mimic'&&st!=='empty'){c.fillStyle=st==='rich'?'#f2da7a':'#8a8f96';rr(c,x+w/2-S*.06,y+h*.78,S*.12,S*.14,S*.02);c.fill();ink(c,S,.012);c.stroke()}ink(c,S);rr(c,x,y,w,h,S*.06);c.stroke();if(st==='rich'){T.gem(c,S,x+w/2,y+h*.4,'#c02a2a')}};
