const sack=(c,S,x,y,r,col,rnd,tied)=>{shadow(c,S,()=>{blob(c,x,y,r,rnd,9,.2);c.fillStyle=col[1];c.fill()});blob(c,x,y,r,rnd,9,.2);c.fillStyle=rg(c,x-r*.3,y-r*.3,0,r*1.2,[col[3],col[1]]);c.fill();ink(c,S,.02);c.stroke();c.strokeStyle='rgba(40,30,10,.4)';c.lineWidth=S*.012;for(let i=0;i<4;i++){const a=rnd()*PI*2;c.beginPath();c.moveTo(x,y);c.lineTo(x+Math.cos(a)*r*.8,y+Math.sin(a)*r*.8);c.stroke()}if(tied){c.fillStyle=col[0];circ(c,x,y,r*.22);c.fill();c.strokeStyle='#5a3c22';c.lineWidth=S*.025;circ(c,x,y,r*.25);c.stroke()}};
