const pot=(c,S,x,y,r,col,rnd,k)=>{shadow(c,S,()=>{circ(c,x,y,r);c.fillStyle=col[1];c.fill()});circ(c,x,y,r);c.fillStyle=rg(c,x-r*.35,y-r*.35,0,r*1.1,[col[3],col[1],col[0]]);c.fill();ink(c,S,.02);c.stroke();if(k==='band'){circ(c,x,y,r*.75);c.strokeStyle=col[0];c.lineWidth=S*.03;c.stroke()}if(k==='lid'){circ(c,x,y,r*.5);c.fillStyle=col[2];c.fill();ink(c,S,.015);c.stroke();circ(c,x,y,r*.12);c.fillStyle=col[0];c.fill()}else{circ(c,x,y,r*.42);c.fillStyle='#160e08';c.fill()}if(k==='crack'){M.cracks(c,S,x-r,y-r,2*r,2*r,rnd,2)}if(k==='handles'){[-1,1].forEach(s=>{c.strokeStyle=col[1];c.lineWidth=S*.04;c.beginPath();c.arc(x+s*r,y,r*.25,s>0?-PI/2:PI/2,s>0?PI/2:PI*1.5);c.stroke()})}};
[['urn','Урна','band',P.red,.3,['храм','склеп']],['amphora','Амфора','handles',P.sand,.28,['корабль','пустыня','рынок']],['jar-lid','Кувшин с крышкой','lid',P.cloth,.26,['кухня','лавка']],['pot-clay','Глиняный горшок','',P.wood,.22,['дом','рынок']],['pot-cracked','Треснувший горшок','crack',P.sand,.3,['руины','склеп']],['vase-blue','Ваза расписная','band',P.blue,.25,['замок','эльфы']],['urn-funeral','Погребальная урна','lid',P.dstone,.3,['склеп']],['jar-big','Большой глиняный чан','handles',P.wood,.42,['кухня','ферма','пустыня']]].forEach(a=>cont(a[0],a[1],a[5],1,1,(c,S,pal,rnd)=>pot(c,S,S/2,S/2,S*a[4],a[3],rnd,a[2])));
