cont('cauldron','Котёл',['кухня','логово ведьмы','лагерь'],1,1,(c,S,pal,rnd)=>{shadow(c,S,()=>{circ(c,S/2,S/2,S*.4);c.fillStyle='#111';c.fill()});circ(c,S/2,S/2,S*.4);c.fillStyle='#1e1f22';c.fill();ink(c,S);c.stroke();circ(c,S/2,S/2,S*.32);c.fillStyle=rg(c,S/2,S/2,0,S*.32,['#8ad048','#2e5a18']);c.fill();for(let i=0;i<5;i++){circ(c,S/2+(rnd()-.5)*S*.4,S/2+(rnd()-.5)*S*.4,S*.03);c.strokeStyle='rgba(220,255,180,.7)';c.lineWidth=S*.01;c.stroke()}M.glow(c,S/2,S/2,S*.5,'rgba(120,220,80,.3)')});
