lite('campfire','Костёр',['лагерь','лес'],1,1,(c,S,rnd)=>{for(let i=0;i<8;i++){const a=i/8*PI*2;M.stoneBlock(c,S,S/2+Math.cos(a)*S*.36-S*.07,S/2+Math.sin(a)*S*.36-S*.06,S*.14,S*.12,P.stone,rnd)}c.fillStyle='#22170e';circ(c,S/2,S/2,S*.27);c.fill();for(let i=0;i<4;i++){c.save();c.translate(S/2,S/2);c.rotate(i*PI/4+rnd()*.3);c.fillStyle='#5a3c22';rr(c,-S*.25,-S*.04,S*.5,S*.08,S*.03);c.fill();ink(c,S,.012);c.stroke();c.restore()}M.flame(c,S,S/2,S/2,2.2);M.flame(c,S,S*.42,S*.55,1.2);M.flame(c,S,S*.58,S*.45,1.2)});
