let mi=0;for(const st in ST)for(const big of [0,1]){const mk=Object.keys(SMAT)[(mi++)%5];const mat=SMAT[mk];const sz=big?2:1;
 add('statue-'+slug(st)+(big?'-big':''),(big?'Большая статуя: ':'Статуя: ')+st+' ('+mk+')','Статуи',STH[st],sz,sz,true,'object',(c,S,rnd,p,W)=>{const m=SMAT[p.mat]||mat;plinth(c,S,W,W,P.stone,rnd,big);const items=ST[st];items.forEach((it,i)=>{if(i<items.length-1)figure(c,S,W/2,W/2,1.4*sz,m,it)});figure(c,S,W/2,W/2,1.4*sz,m,items[items.length-1]);if(p.dmg)M.cracks(c,S,0,0,W,W,rnd,4)})}
