pillar('square','Квадратная опора',['подземелье','крепость','шахта'],(c,S,rnd)=>{shadow(c,S,()=>{c.fillStyle='#555';c.fillRect(S*.1,S*.1,S*.8,S*.8)});stoneBlock(c,S,S*.1,S*.1,S*.8,S*.8,P.stone,rnd);c.strokeStyle='rgba(0,0,0,.3)';c.beginPath();c.moveTo(S*.1,S*.5);c.lineTo(S*.9,S*.5);c.stroke()});
pillar('broken','Обломок колонны',['руины'],(c,S,rnd)=>{circ(c,S/2,S/2,S*.38);c.fillStyle=rg(c,S*.4,S*.4,0,S*.4,['#d6d1c6','#8a867e']);c.fill();ink(c,S);c.stroke();c.fillStyle='rgba(60,50,40,.4)';blob(c,S*.55,S*.45,S*.22,rnd,8,.6);c.fill();M.cracks(c,S,S*.2,S*.2,S*.6,S*.6,rnd,3)});
pillar('vines','Колонна, увитая плющом',['руины','джунгли','эльфы'],(c,S,rnd)=>{M.byId['md3-pillar-round'].draw(c,S,{},rnd);c.strokeStyle='#2e5a1e';c.lineWidth=S*.03;c.beginPath();for(let a=0;a<PI*4;a+=.2){const r=S*(.1+a/(PI*4)*.28);c.lineTo(S/2+Math.cos(a)*r,S/2+Math.sin(a)*r)}c.stroke();for(let i=0;i<14;i++){const a=rnd()*PI*2,r=S*(.1+rnd()*.3);ell(c,S/2+Math.cos(a)*r,S/2+Math.sin(a)*r,S*.05,S*.025,a);c.fillStyle='#4a8a2a';c.fill()}});
pillar('wood','Деревянный столб',['таверна','шахта','деревня'],(c,S,rnd)=>{circ(c,S/2,S/2,S*.2);c.fillStyle=P.wood[1];c.fill();ink(c,S);c.stroke();c.strokeStyle='rgba(30,15,5,.5)';c.lineWidth=S*.01;for(let i=1;i<4;i++){circ(c,S/2,S/2,S*.05*i);c.stroke()}});
pillar('crystal','Кристаллический столп',['подземье','башня мага'],(c,S,rnd)=>{glow(c,S/2,S/2,S*.7,'rgba(140,200,255,.35)');const pts=[];for(let i=0;i<6;i++){const a=i/6*PI*2;pts.push([S/2+Math.cos(a)*S*.36,S/2+Math.sin(a)*S*.36])}poly(c,pts);c.fillStyle=lg(c,0,0,S,S,['#e0f4ff','#4a8ad8','#1a2a5a']);c.fill();ink(c,S);c.stroke();pts.forEach(q=>{c.beginPath();c.moveTo(S/2,S/2);c.lineTo(q[0],q[1]);c.strokeStyle='rgba(255,255,255,.4)';c.stroke()})});
pillar('obelisk','Обелиск',['пустыня','руины','кладбище'],(c,S,rnd)=>{shadow(c,S,()=>{c.fillStyle='#444';c.fillRect(S*.2,S*.2,S*.6,S*.6)});stoneBlock(c,S,S*.2,S*.2,S*.6,S*.6,P.dstone,rnd);poly(c,[[S*.3,S*.3],[S*.7,S*.3],[S*.7,S*.7],[S*.3,S*.7]]);c.fillStyle='#5a5960';c.fill();c.strokeStyle=M.INK;c.beginPath();c.moveTo(S*.3,S*.3);c.lineTo(S*.7,S*.7);c.moveTo(S*.7,S*.3);c.lineTo(S*.3,S*.7);c.stroke()});
