altar('stone','Каменный алтарь',['храм','руины'],2,P.stone,(c,S,rnd,W)=>{T.candle(c,S,S*.3,S*.35);T.candle(c,S,W-S*.3,S*.35);T.openbook(c,S,W/2,S*.5,0)});
altar('blood','Окровавленный жертвенник',['логово культа','инфернальное'],2,P.dstone,(c,S,rnd,W)=>{c.fillStyle='rgba(120,10,10,.85)';blob(c,W/2,S*.5,S*.3,rnd,10,.5);c.fill();for(let i=0;i<5;i++){c.beginPath();c.moveTo(W/2+(rnd()-.5)*S*.5,S*.6);c.lineTo(W/2+(rnd()-.5)*S*.6,S*.9);c.strokeStyle='rgba(120,10,10,.8)';c.lineWidth=S*.03;c.stroke()}T.knife(c,S,W*.75,S*.45,1.2);T.candle(c,S,S*.25,S*.3)});
altar('gold','Золотой алтарь',['храм','небесное'],2,P.marble,(c,S,rnd,W)=>{c.fillStyle='#d8b440';c.fillRect(S*.2,S*.25,W-S*.4,S*.5);ink(c,S,.02);c.strokeRect(S*.2,S*.25,W-S*.4,S*.5);circ(c,W/2,S*.5,S*.15);c.fillStyle='#f2da7a';c.fill();c.stroke();glow(c,W/2,S*.5,S*.9,'rgba(255,230,150,.35)')});
