altar('druid','Друидский алтарь из пня',['лес','друиды'],1,P.moss,(c,S,rnd,W)=>{c.fillStyle='#c8a070';circ(c,S/2,S/2,S*.25);c.fill();for(let i=0;i<5;i++){ell(c,S*(.3+rnd()*.4),S*(.3+rnd()*.4),S*.06,S*.03,rnd()*3);c.fillStyle='#4a8a2a';c.fill()}c.fillStyle='#a8281e';circ(c,S*.5,S*.5,S*.05);c.fill()});
altar('infernal','Алтарь с пентаграммой',['инфернальное','логово культа'],2,P.dstone,(c,S,rnd,W)=>{c.strokeStyle='#d8320e';c.lineWidth=S*.025;c.beginPath();for(let i=0;i<=5;i++){const a=-PI/2+i*PI*4/5;c.lineTo(W/2+Math.cos(a)*S*.3,S*.5+Math.sin(a)*S*.3)}c.stroke();circ(c,W/2,S*.5,S*.32);c.stroke();glow(c,W/2,S*.5,S*.6,'rgba(255,60,20,.35)')});
altar('celestial','Небесный алтарь',['небесное','храм'],2,P.marble,(c,S,rnd,W)=>{c.strokeStyle='#d8b440';c.lineWidth=S*.02;for(let i=0;i<12;i++){const a=i/12*PI*2;c.beginPath();c.moveTo(W/2+Math.cos(a)*S*.1,S*.5+Math.sin(a)*S*.1);c.lineTo(W/2+Math.cos(a)*S*.32,S*.5+Math.sin(a)*S*.32);c.stroke()}circ(c,W/2,S*.5,S*.1);c.fillStyle='#fff8d0';c.fill();glow(c,W/2,S*.5,S,'rgba(255,250,200,.4)')});
altar('slab','Жертвенная плита с оковами',['логово культа','тюрьма'],2,P.stone,(c,S,rnd,W)=>{c.strokeStyle='#45484d';c.lineWidth=S*.03;[[.3,.3],[.3,.7],[W/S-.3,.3],[W/S-.3,.7]].forEach(q=>{circ(c,S*q[0],S*q[1],S*.06);c.stroke()});c.fillStyle='rgba(100,10,10,.5)';blob(c,W/2,S*.5,S*.2,rnd,8,.5);c.fill()});
add('font-holy','Купель со святой водой','Культ',['храм'],1,1,true,'object',(c,S,rnd)=>{const pts=[];for(let i=0;i<8;i++){const a=PI/8+i*PI/4;pts.push([S/2+Math.cos(a)*S*.42,S/2+Math.sin(a)*S*.42])}shadow(c,S,()=>{poly(c,pts);c.fillStyle='#888';c.fill()});poly(c,pts);c.fillStyle=lg(c,0,0,S,S,['#f4f0e6','#a8a399']);c.fill();ink(c,S);c.stroke();circ(c,S/2,S/2,S*.28);c.fillStyle=rg(c,S*.45,S*.45,0,S*.3,['#d0f0ff','#4a8ab0']);c.fill();ink(c,S,.02);c.stroke();glow(c,S/2,S/2,S*.5,'rgba(200,240,255,.35)')});
