add('totem','Тотемный столб','Культ',['племя','степь','север'],1,1,true,'object',(c,S,rnd)=>{circ(c,S/2,S/2,S*.25);c.fillStyle=lg(c,0,0,S,S,['#b8642a','#45301e']);c.fill();ink(c,S);c.stroke();[-1,1].forEach(s=>{poly(c,[[S/2+s*S*.2,S*.42],[S/2+s*S*.48,S*.35],[S/2+s*S*.48,S*.5],[S/2+s*S*.2,S*.58]]);c.fillStyle='#952b22';c.fill();ink(c,S,.015);c.stroke()});c.fillStyle='#f0e6c8';circ(c,S*.43,S*.45,S*.04);c.fill();circ(c,S*.57,S*.45,S*.04);c.fill()});
