sarc('stone','Каменный саркофаг',['склеп'],(c,S,rnd)=>{shadow(c,S,()=>{c.fillStyle='#444';c.fillRect(S*.1,S*.1,S*.8,S*1.8)});stoneBlock(c,S,S*.1,S*.1,S*.8,S*1.8,P.stone,rnd);c.strokeStyle='rgba(0,0,0,.35)';c.lineWidth=S*.02;c.strokeRect(S*.2,S*.2,S*.6,S*1.6);c.beginPath();c.moveTo(S/2,S*.4);c.lineTo(S/2,S*1.4);c.moveTo(S*.3,S*.75);c.lineTo(S*.7,S*.75);c.stroke()});
sarc('effigy','Саркофаг с изваянием рыцаря',['склеп','замок'],(c,S,rnd)=>{shadow(c,S,()=>{c.fillStyle='#444';c.fillRect(S*.08,S*.08,S*.84,S*1.84)});stoneBlock(c,S,S*.08,S*.08,S*.84,S*1.84,P.marble,rnd);circ(c,S/2,S*.38,S*.13);c.fillStyle='#bdb8ae';c.fill();ink(c,S,.02);c.stroke();rr(c,S*.28,S*.52,S*.44,S*.9,S*.15);c.fill();c.stroke();c.fillStyle='#8a867e';c.fillRect(S*.47,S*.6,S*.06,S*1.1);c.fillRect(S*.36,S*.68,S*.28,S*.05);rr(c,S*.32,S*1.45,S*.36,S*.35,S*.1);c.fillStyle='#bdb8ae';c.fill();c.stroke()});
sarc('open','Открытый саркофаг со скелетом',['склеп','подземелье'],(c,S,rnd)=>{stoneBlock(c,S,S*.1,S*.1,S*.8,S*1.8,P.stone,rnd);c.fillStyle='#160e08';c.fillRect(S*.2,S*.2,S*.6,S*1.6);M.SKEL&&M.SKEL(c,S,S/2,S,0.8,rnd);c.save();c.translate(S*.95,S*1.1);c.rotate(.25);stoneBlock(c,S,-S*.12,-S*.85,S*.24,S*1.7,P.stone,rnd);c.restore()});
sarc('ornate','Золочёный саркофаг',['сокровищница','пустыня','склеп'],(c,S,rnd)=>{rr(c,S*.12,S*.08,S*.76,S*1.84,S*.3);c.fillStyle=lg(c,0,0,S,0,['#7a5a10','#f2da7a','#7a5a10']);c.fill();ink(c,S);c.stroke();circ(c,S/2,S*.45,S*.2);c.fillStyle='#d8b440';c.fill();c.stroke();c.strokeStyle='#2f4f86';c.lineWidth=S*.04;for(let i=0;i<5;i++){c.beginPath();c.moveTo(S*.25,S*(.8+i*.2));c.lineTo(S*.75,S*(.8+i*.2));c.stroke()}T.gem(c,S,S/2,S*.68,'#2a7ac0')});
sarc('coffin','Деревянный гроб',['кладбище','склеп','деревня'],(c,S,rnd)=>{const pts=[[S*.35,S*.08],[S*.65,S*.08],[S*.85,S*.55],[S*.72,S*1.92],[S*.28,S*1.92],[S*.15,S*.55]];shadow(c,S,()=>{poly(c,pts);c.fillStyle='#333';c.fill()});c.save();poly(c,pts);c.clip();wood(c,S,0,0,S,2*S,P.dwood,rnd,'v',3);c.restore();ink(c,S);poly(c,pts);c.stroke();c.strokeStyle='#c49a3c';c.lineWidth=S*.03;c.beginPath();c.moveTo(S/2,S*.4);c.lineTo(S/2,S*1.1);c.moveTo(S*.35,S*.6);c.lineTo(S*.65,S*.6);c.stroke()});
sarc('coffin-open','Открытый пустой гроб',['кладбище','логово вампира'],(c,S,rnd)=>{const pts=[[S*.35,S*.08],[S*.65,S*.08],[S*.85,S*.55],[S*.72,S*1.92],[S*.28,S*1.92],[S*.15,S*.55]];poly(c,pts);c.fillStyle=P.dwood[1];c.fill();ink(c,S);c.stroke();const ins=pts.map(q=>[S/2+(q[0]-S/2)*.8,S+(q[1]-S)*.92]);poly(c,ins);c.fillStyle='#6e1e18';c.fill();c.fillStyle='rgba(255,255,255,.12)';for(let i=0;i<5;i++){c.fillRect(S*.3,S*(.4+i*.3),S*.4,S*.03)}});
sarc('vampire','Гроб вампира с землёй',['логово вампира','замок'],(c,S,rnd)=>{const pts=[[S*.35,S*.08],[S*.65,S*.08],[S*.88,S*.55],[S*.74,S*1.92],[S*.26,S*1.92],[S*.12,S*.55]];shadow(c,S,()=>{poly(c,pts);c.fillStyle='#000';c.fill()});poly(c,pts);c.fillStyle='#141418';c.fill();ink(c,S);c.stroke();const ins=pts.map(q=>[S/2+(q[0]-S/2)*.8,S+(q[1]-S)*.92]);poly(c,ins);c.fillStyle='#3a2414';c.fill();for(let i=0;i<40;i++){circ(c,S*(.3+rnd()*.4),S*(.3+rnd()*1.4),S*.015);c.fillStyle='#22140a';c.fill()}c.fillStyle='#8a1e2a';c.fillRect(S*.12,S*.5,S*.06,S*.3)});
const tomb=(id,n,f)=>add('grave-'+id,n,'Культ',['кладбище'],1,1,true,'object',f);
