  c.save();draw();c.clip();c.strokeStyle=col[2];c.lineWidth=S*.015;for(let i=0;i<w*h*4;i++){const x=rnd()*W,y=rnd()*H;c.beginPath();c.moveTo(x,y);c.quadraticCurveTo(x+S*.1,y-S*.04,x+S*.2,y);c.stroke()}
