const sword=(c,S,x,y,a,l)=>{c.save();c.translate(x,y);c.rotate(a);c.fillStyle=lg(c,-S*.02,0,S*.02,0,['#d0d4da','#7a7e84']);poly(c,[[-S*.025,-l*.5],[0,-l*.6],[S*.025,-l*.5],[S*.025,l*.25],[-S*.025,l*.25]]);c.fill();ink(c,S,.01);c.stroke();c.fillStyle='#9a7328';c.fillRect(-S*.08,l*.25,S*.16,S*.03);c.fillStyle='#45301e';c.fillRect(-S*.018,l*.25+S*.03,S*.036,S*.1);c.restore()};
arm('rack-swords','Стойка с мечами',['казарма','крепость','оружейная'],2,1,(c,S,rnd,p,W)=>{wood(c,S,S*.05,S*.35,W-S*.1,S*.3,P.dwood,rnd,'h',1);for(let i=0;i<6;i++)sword(c,S,S*(.25+i*.3),S*.5,PI/2,S*.7)});
arm('rack-spears','Стойка с копьями',['казарма','крепость'],2,1,(c,S,rnd,p,W)=>{wood(c,S,S*.05,S*.4,W-S*.1,S*.2,P.dwood,rnd,'h',1);for(let i=0;i<7;i++){const x=S*(.2+i*.26);c.strokeStyle='#6e5034';c.lineWidth=S*.03;c.beginPath();c.moveTo(x,S*.1);c.lineTo(x,S*.9);c.stroke();poly(c,[[x,S*.02],[x+S*.04,S*.14],[x-S*.04,S*.14]]);c.fillStyle='#a8adb4';c.fill()}});
arm('rack-bows','Стойка с луками',['казарма','эльфы','лагерь'],2,1,(c,S,rnd,p,W)=>{wood(c,S,S*.05,S*.42,W-S*.1,S*.16,P.wood,rnd,'h',1);for(let i=0;i<4;i++){const x=S*(.3+i*.45);c.strokeStyle='#7a5432';c.lineWidth=S*.035;c.beginPath();c.arc(x+S*.3,S*.5,S*.36,PI*.75,PI*1.25);c.stroke();c.strokeStyle='#e6e0d0';c.lineWidth=S*.008;c.beginPath();c.moveTo(x+S*.3+Math.cos(PI*.75)*S*.36,S*.5+Math.sin(PI*.75)*S*.36);c.lineTo(x+S*.3+Math.cos(PI*1.25)*S*.36,S*.5+Math.sin(PI*1.25)*S*.36);c.stroke()}});
arm('armor-stand','Стойка с доспехом',['казарма','замок','оружейная'],1,1,(c,S,rnd)=>{circ(c,S/2,S/2,S*.35);c.fillStyle='rgba(0,0,0,.25)';c.fill();ell(c,S/2,S*.55,S*.3,S*.16);c.fillStyle=lg(c,S*.2,0,S*.8,0,['#63676d','#c0c4ca','#63676d']);c.fill();ink(c,S,.02);c.stroke();circ(c,S/2,S*.42,S*.13);c.fillStyle='#8a8f96';c.fill();c.stroke();c.fillStyle='#22170e';c.fillRect(S*.43,S*.4,S*.14,S*.03);[-1,1].forEach(s=>{circ(c,S/2+s*S*.3,S*.55,S*.08);c.fillStyle='#8a8f96';c.fill();c.stroke()})});
arm('dummy','Тренировочное чучело',['казарма','двор','лагерь'],1,1,(c,S,rnd)=>{c.fillStyle='#5a3c22';c.fillRect(S*.15,S*.46,S*.7,S*.08);circ(c,S/2,S/2,S*.2);c.fillStyle='#c8b070';c.fill();ink(c,S,.02);c.stroke();c.strokeStyle='rgba(110,80,30,.7)';c.lineWidth=S*.012;for(let i=0;i<12;i++){const a=rnd()*PI*2;c.beginPath();c.moveTo(S/2,S/2);c.lineTo(S/2+Math.cos(a)*S*.2,S/2+Math.sin(a)*S*.2);c.stroke()}c.fillStyle='#952b22';c.fillRect(S*.45,S*.3,S*.1,S*.04)});
