const stallGoods={'фрукты':(c,S,x,y,rnd)=>{for(let i=0;i<7;i++){circ(c,x+(rnd()-.5)*S*.35,y+(rnd()-.5)*S*.25,S*.05);c.fillStyle=['#a8281e','#d8a030','#7a9a3a','#7a2e5a'][i%4];c.fill()}},'рыба':(c,S,x,y,rnd)=>{for(let i=0;i<4;i++){c.save();c.translate(x+(rnd()-.5)*S*.3,y+(rnd()-.5)*S*.2);c.rotate(rnd()*PI);ell(c,0,0,S*.12,S*.04);c.fillStyle='#8a9aa4';c.fill();c.restore()}},'ткани':(c,S,x,y,rnd)=>{['#952b22','#2f4f86','#406236','#d8b440'].forEach((k,i)=>{c.fillStyle=k;c.fillRect(x-S*.2+i*S*.1,y-S*.15,S*.09,S*.3)})},'оружие':(c,S,x,y,rnd)=>{for(let i=0;i<3;i++)T.knife(c,S,x-S*.12+i*S*.12,y,PI/2)},'гончарня':(c,S,x,y,rnd)=>{for(let i=0;i<4;i++){circ(c,x-S*.15+i*S*.1,y,S*.05);c.fillStyle='#a8644a';c.fill();ink(c,S,.01);c.stroke()}},'специи':(c,S,x,y,rnd)=>{['#c8781e','#a8281e','#d8c040','#6e4a2a','#7a9a3a'].forEach((k,i)=>{circ(c,x-S*.2+i*S*.1,y,S*.045);c.fillStyle=k;c.fill()})},'цветы':(c,S,x,y,rnd)=>{for(let i=0;i<9;i++){circ(c,x+(rnd()-.5)*S*.4,y+(rnd()-.5)*S*.25,S*.03);c.fillStyle=['#e86aa0','#f4f0e6','#d8b440','#a878c8'][i%4];c.fill()}},'мясо':(c,S,x,y,rnd)=>{for(let i=0;i<3;i++){ell(c,x-S*.12+i*S*.12,y,S*.06,S*.09);c.fillStyle='#a8483a';c.fill();ink(c,S,.01);c.stroke()}},'книги':(c,S,x,y,rnd)=>{for(let i=0;i<4;i++)T.book(c,S,x-S*.15+i*S*.1,y,rnd()*.6,['#6e1e18','#1f3560','#2d4626','#5a3470'][i])},'зелья':(c,S,x,y,rnd)=>{for(let i=0;i<4;i++)T.potion(c,S,x-S*.15+i*S*.1,y,['#b8463a','#4a6fa8','#5a8048','#7a4f94'][i])},'хлеб':(c,S,x,y,rnd)=>{for(let i=0;i<3;i++)T.bread(c,S,x-S*.12+i*S*.12,y,rnd)},'сыр':(c,S,x,y,rnd)=>{for(let i=0;i<3;i++){circ(c,x-S*.12+i*S*.12,y,S*.06);c.fillStyle='#e8c050';c.fill();ink(c,S,.01);c.stroke()}}};
