wall('tapestry-stars','Гобелен «Звёздное небо»',['башня мага','эльфы'],3,(c,S,rnd,p,W)=>{c.fillStyle='#14233e';c.fillRect(S*.05,0,W-S*.1,S*.35);c.fillStyle='#f2da7a';for(let i=0;i<30;i++){circ(c,S*.1+rnd()*(W-S*.2),S*.03+rnd()*S*.28,S*.012);c.fill()}circ(c,W*.7,S*.17,S*.08);c.fill();c.fillStyle='#14233e';circ(c,W*.72,S*.15,S*.07);c.fill()});
wall('tapestry-map','Гобелен-карта королевства',['замок','штаб'],3,(c,S,rnd,p,W)=>{c.fillStyle='#d9c79a';c.fillRect(S*.05,0,W-S*.1,S*.38);c.fillStyle='rgba(64,98,54,.6)';for(let i=0;i<5;i++){blob(c,S*.3+rnd()*(W-S*.6),S*.18,S*.12,rnd,8,.5);c.fill()}c.strokeStyle='#2f4f86';c.lineWidth=S*.015;c.beginPath();c.moveTo(S*.1,S*.3);c.bezierCurveTo(W*.3,S*.05,W*.6,S*.35,W-S*.1,S*.1);c.stroke();c.strokeStyle='#6e1e18';c.lineWidth=S*.025;c.strokeRect(S*.05,0,W-S*.1,S*.38)});
wall('trophy-deer','Оленьи рога на стене',['охотничий домик','таверна','замок'],1,(c,S)=>{c.fillStyle='#45301e';ell(c,S/2,S*.08,S*.15,S*.08);c.fill();ell(c,S/2,S*.18,S*.08,S*.12);c.fillStyle='#8a6a4a';c.fill();ink(c,S,.015);c.stroke();c.strokeStyle='#d8cfb0';c.lineWidth=S*.03;[-1,1].forEach(s=>{c.beginPath();c.moveTo(S/2+s*S*.06,S*.1);c.quadraticCurveTo(S/2+s*S*.3,S*.05,S/2+s*S*.42,S*.25);c.moveTo(S/2+s*S*.22,S*.08);c.lineTo(S/2+s*S*.25,S*.25);c.moveTo(S/2+s*S*.33,S*.12);c.lineTo(S/2+s*S*.4,S*.05);c.stroke()})});
wall('trophy-boar','Голова вепря на стене',['охотничий домик','таверна'],1,(c,S)=>{ell(c,S/2,S*.2,S*.17,S*.18);c.fillStyle='#4a3424';c.fill();ink(c,S,.015);c.stroke();ell(c,S/2,S*.33,S*.08,S*.06);c.fillStyle='#6a4a3a';c.fill();c.stroke();c.strokeStyle='#e8e0c8';c.lineWidth=S*.025;[-1,1].forEach(s=>{c.beginPath();c.moveTo(S/2+s*S*.06,S*.32);c.quadraticCurveTo(S/2+s*S*.16,S*.36,S/2+s*S*.14,S*.25);c.stroke()})});
wall('trophy-swords','Скрещённые мечи со щитом',['замок','казарма'],1,(c,S)=>{[PI/4,-PI/4].forEach(a=>{c.save();c.translate(S/2,S*.2);c.rotate(a);c.fillStyle='#c0c4ca';c.fillRect(-S*.02,-S*.3,S*.04,S*.5);c.fillStyle='#9a7328';c.fillRect(-S*.07,S*.18,S*.14,S*.03);c.restore()});shieldSig(c,S,S/2,S*.17,S*.13,'башня','лазурный')});
wall('trophy-dragon','Голова дракона на стене',['замок','логово героя'],2,(c,S,rnd,p,W)=>{c.fillStyle='#45301e';rr(c,W/2-S*.3,0,S*.6,S*.12,S*.04);c.fill();c.beginPath();c.moveTo(W/2-S*.3,S*.1);c.quadraticCurveTo(W/2-S*.35,S*.5,W/2,S*.75);c.quadraticCurveTo(W/2+S*.35,S*.5,W/2+S*.3,S*.1);c.closePath();c.fillStyle=lg(c,W/2-S*.3,0,W/2+S*.3,0,['#2a4a2a','#5a8a4a','#2a4a2a']);c.fill();ink(c,S);c.stroke();c.fillStyle='#ffb030';circ(c,W/2-S*.13,S*.3,S*.04);c.fill();circ(c,W/2+S*.13,S*.3,S*.04);c.fill();[-1,1].forEach(s=>{c.strokeStyle='#d8cfb0';c.lineWidth=S*.06;c.beginPath();c.moveTo(W/2+s*S*.22,S*.15);c.quadraticCurveTo(W/2+s*S*.6,S*.05,W/2+s*S*.75,S*.3);c.stroke()})});
wall('trophy-fish','Чучело огромной рыбы',['таверна','порт'],2,(c,S,rnd,p,W)=>{wood(c,S,S*.2,0,W-S*.4,S*.12,P.dwood,rnd,'h',1);ell(c,W/2,S*.3,S*.7,S*.16);c.fillStyle=lg(c,0,S*.15,0,S*.45,['#8aa0a8','#3a5a64']);c.fill();ink(c,S,.02);c.stroke();poly(c,[[W/2+S*.65,S*.3],[W/2+S*.9,S*.12],[W/2+S*.9,S*.48]]);c.fill();c.stroke();c.fillStyle='#000';circ(c,W/2-S*.5,S*.27,S*.03);c.fill()});
wall('painting-portrait','Портрет предка',['замок','особняк'],1,(c,S)=>{c.fillStyle='#9a7328';c.fillRect(S*.2,0,S*.6,S*.14);c.fillStyle='#3a2a1a';c.fillRect(S*.25,S*.02,S*.5,S*.1);c.fillStyle='#c8a080';circ(c,S/2,S*.06,S*.03);c.fill()});
