wall('painting-cursed','Проклятый портрет (глаза следят)',['особняк','логово вампира'],1,(c,S)=>{c.fillStyle='#22170e';c.fillRect(S*.2,0,S*.6,S*.14);c.fillStyle='#2a1a2a';c.fillRect(S*.25,S*.02,S*.5,S*.1);c.fillStyle='#ff3030';circ(c,S*.45,S*.06,S*.012);c.fill();circ(c,S*.55,S*.06,S*.012);c.fill();glow(c,S/2,S*.06,S*.2,'rgba(255,40,40,.3)')});
