wall('shelf-trophies','Полка с трофеями',['таверна','охотничий домик','гильдия'],2,(c,S,rnd,p,W)=>{wood(c,S,S*.05,0,W-S*.1,S*.25,P.dwood,rnd,'h',1);T.skull(c,S,S*.35,S*.12,.8);T.gem(c,S,S*.75,S*.12,'#2a7ac0');circ(c,S*1.15,S*.12,S*.08);c.fillStyle='#d8b440';c.fill();T.potion(c,S,S*1.6,S*.12,'#7a4f94')});
