mine('supports','Крепь (опорные брёвна)',1,1,true,(c,S,rnd)=>{[[.12,.12],[.88,.12],[.12,.88],[.88,.88]].forEach(q=>{circ(c,S*q[0],S*q[1],S*.1);c.fillStyle=P.wood[1];c.fill();ink(c,S,.02);c.stroke()});wood(c,S,0,S*.05,S,S*.14,P.wood,rnd,'h',1);wood(c,S,0,S*.81,S,S*.14,P.wood,rnd,'h',1)},'Механизмы');
const ORE={'золото':['#f2da7a','#b08a1c'],'железо':['#b87a5a','#6e3a20'],'мифрил':['#e0f0ff','#7aa0c8'],'уголь':['#2a2a2a','#0a0a0a'],'самоцветы':['#e04a8a','#4a8ae0']};
for(const o in ORE){mine('vein-'+slug(o),'Рудная жила: '+o,2,1,true,(c,S,rnd,p,W)=>{stoneBlock(c,S,0,0,W,S*.45,P.dstone,rnd);c.strokeStyle=ORE[o][1];c.lineWidth=S*.06;c.beginPath();c.moveTo(0,S*.25);c.bezierCurveTo(W*.3,S*.05,W*.6,S*.4,W,S*.2);c.stroke();for(let i=0;i<10;i++){const x=rnd()*W,y=S*(.1+rnd()*.3);poly(c,[[x,y-S*.03],[x+S*.04,y],[x,y+S*.03],[x-S*.04,y]]);c.fillStyle=ORE[o][i%2];c.fill()}if(o==='мифрил'||o==='самоцветы')glow(c,W/2,S*.25,S*.8,'rgba(200,220,255,.25)')});
 mine('ore-'+slug(o),'Куча руды: '+o,1,1,false,(c,S,rnd)=>{for(let i=0;i<12;i++){const x=S*(.25+rnd()*.5),y=S*(.25+rnd()*.5);blob(c,x,y,S*(.05+rnd()*.06),rnd,6,.4);c.fillStyle=i%3?'#5a5751':ORE[o][0];c.fill();ink(c,S,.01);c.stroke()}})}
mine('pick-rack','Стойка с кирками',1,1,true,(c,S,rnd)=>{wood(c,S,S*.1,S*.4,S*.8,S*.2,P.dwood,rnd,'h',1);for(let i=0;i<3;i++){const x=S*(.25+i*.25);c.fillStyle='#6e5034';c.fillRect(x-S*.02,S*.15,S*.04,S*.7);c.strokeStyle='#63676d';c.lineWidth=S*.04;c.beginPath();c.moveTo(x-S*.12,S*.22);c.quadraticCurveTo(x,S*.12,x+S*.12,S*.22);c.stroke()}},'Механизмы');
mine('ale-keg-giant','Гигантская бочка эля',2,2,true,(c,S,rnd,p,W)=>{M.T&&0;const pal=P.wood;shadow(c,S,()=>{circ(c,W/2,W/2,S*.9);c.fillStyle=pal[1];c.fill()});c.save();circ(c,W/2,W/2,S*.9);c.clip();wood(c,S,0,0,W,W,pal,rnd,'v',9);c.restore();circ(c,W/2,W/2,S*.9);c.strokeStyle='#2b2d30';c.lineWidth=S*.08;c.stroke();circ(c,W/2,W/2,S*.7);c.lineWidth=S*.04;c.stroke();c.fillStyle='#c49a3c';c.font=`bold ${S*.5}px serif`;c.textAlign='center';c.textBaseline='middle';c.fillText('ᚱ',W/2,W/2)},'Ёмкости');
mine('rune-brazier','Рунная жаровня дварфов',1,1,true,(c,S,rnd)=>{const pts=[];for(let i=0;i<6;i++){const a=i/6*PI*2;pts.push([S/2+Math.cos(a)*S*.42,S/2+Math.sin(a)*S*.42])}poly(c,pts);c.fillStyle='#45484d';c.fill();ink(c,S);c.stroke();c.strokeStyle='#c49a3c';c.lineWidth=S*.02;pts.forEach(q=>{c.beginPath();c.moveTo(q[0]*.8+S*.1,q[1]*.8+S*.1);c.lineTo(q[0]*.7+S*.15,q[1]*.7+S*.15);c.stroke()});circ(c,S/2,S/2,S*.25);c.fillStyle=rg(c,S/2,S/2,0,S*.25,['#ffe080','#ff7a10','#4a1004']);c.fill();glow(c,S/2,S/2,S,'rgba(255,140,40,.35)')},'Свет');
mine('pillar-carved','Резная колонна дварфов',1,1,true,(c,S,rnd)=>{const pts=[];for(let i=0;i<8;i++){const a=PI/8+i*PI/4;pts.push([S/2+Math.cos(a)*S*.44,S/2+Math.sin(a)*S*.44])}poly(c,pts);c.fillStyle=lg(c,0,0,S,S,['#8a867e','#3a3940']);c.fill();ink(c,S);c.stroke();circ(c,S/2,S/2,S*.25);c.strokeStyle='#c49a3c';c.lineWidth=S*.03;c.stroke();c.beginPath();for(let i=0;i<4;i++){const a=i/4*PI*2+PI/4;c.moveTo(S/2,S/2);c.lineTo(S/2+Math.cos(a)*S*.25,S/2+Math.sin(a)*S*.25)}c.stroke()},'Статуи');
mine('lava-channel','Лавовый жёлоб кузни',3,1,false,(c,S,rnd,p,W)=>{stoneBlock(c,S,0,S*.2,W,S*.6,P.dstone,rnd);c.fillStyle=lg(c,0,S*.3,0,S*.7,['#ffb030','#d8520e','#8a1e06']);c.fillRect(0,S*.32,W,S*.36);c.fillStyle='rgba(50,15,5,.6)';for(let i=0;i<8;i++){blob(c,rnd()*W,S/2,S*.08,rnd,6,.5);c.fill()}glow(c,W/2,S/2,S*1.5,'rgba(255,100,20,.3)')},'Вода и лава');
mine('mithril-anvil','Мифриловая наковальня',1,1,true,(c,S,rnd)=>{stoneBlock(c,S,S*.2,S*.2,S*.6,S*.6,P.dstone,rnd);c.beginPath();c.moveTo(S*.08,S*.5);c.quadraticCurveTo(S*.2,S*.38,S*.3,S*.38);c.lineTo(S*.82,S*.38);c.lineTo(S*.82,S*.62);c.lineTo(S*.3,S*.62);c.quadraticCurveTo(S*.2,S*.62,S*.08,S*.5);c.fillStyle=lg(c,0,S*.38,0,S*.62,['#ffffff','#a0c0e0','#5a7aa0']);c.fill();ink(c,S,.02);c.stroke();glow(c,S/2,S/2,S*.6,'rgba(200,230,255,.35)')},'Механизмы');
mine('mushroom-farm','Грибная ферма подземья',2,2,false,(c,S,rnd,p,W)=>{c.fillStyle='rgba(60,40,30,.6)';c.fillRect(S*.05,S*.05,W-S*.1,W-S*.1);for(let i=0;i<4;i++)for(let j=0;j<4;j++){const x=S*(.3+i*.47),y=S*(.3+j*.47),r=S*(.1+rnd()*.06);circ(c,x,y,r);c.fillStyle=rg(c,x,y,0,r,['#e0c8ff','#7a4aa8']);c.fill();ink(c,S,.012);c.stroke()}},'Природа');
// ---- инфернальное ----
const inf=(id,n,w,h,solid,f,cat,layer)=>add('inf-'+id,n,cat||'Культ',['инфернальное','бездна','логово демона'],w,h,solid,layer||'object',f);
inf('brimstone','Серные шипы',1,1,true,(c,S,rnd)=>{for(let i=0;i<6;i++){const x=S*(.2+rnd()*.6),y=S*(.2+rnd()*.6),r=S*(.08+rnd()*.1);for(let k=3;k>0;k--){blob(c,x,y,r*k/3,rnd,6,.4);c.fillStyle=['#e8c040','#8a4a10','#2a1008'][k-1];c.fill()}}glow(c,S/2,S/2,S*.6,'rgba(255,90,20,.25)')},'Природа');
inf('hooks','Цепи с крюками',1,1,false,(c,S,rnd)=>{c.strokeStyle='#45484d';c.lineWidth=S*.02;for(let i=0;i<4;i++){const x=S*(.2+i*.2);c.beginPath();for(let y=0;y<S*.7;y+=S*.06){c.moveTo(x,y);c.lineTo(x,y+S*.04)}c.stroke();c.lineWidth=S*.03;c.beginPath();c.arc(x+S*.04,S*.75,S*.05,PI,PI*.2,true);c.stroke();c.lineWidth=S*.02}c.fillStyle='rgba(110,10,8,.6)';circ(c,S*.45,S*.85,S*.06);c.fill()},'Механизмы','top');
inf('soul-cage','Клетка душ',1,1,true,(c,S,rnd)=>{glow(c,S/2,S/2,S*.6,'rgba(120,255,200,.4)');circ(c,S/2,S/2,S*.35);c.strokeStyle='#22242a';c.lineWidth=S*.04;c.stroke();for(let i=0;i<8;i++){const a=i/8*PI*2;c.beginPath();c.moveTo(S/2,S/2);c.lineTo(S/2+Math.cos(a)*S*.35,S/2+Math.sin(a)*S*.35);c.lineWidth=S*.02;c.stroke()}for(let i=0;i<3;i++){c.fillStyle='rgba(200,255,230,.7)';blob(c,S*(.4+rnd()*.2),S*(.4+rnd()*.2),S*.07,rnd,7,.5);c.fill()}},'Магия');
inf('flesh-pillar','Столп из плоти',1,1,true,(c,S,rnd)=>{blob(c,S/2,S/2,S*.4,rnd,11,.3);c.fillStyle=rg(c,S*.45,S*.45,0,S*.42,['#d88a7a','#8a3a32','#3a0e0a']);c.fill();ink(c,S);c.stroke();for(let i=0;i<4;i++){const x=S*(.3+rnd()*.4),y=S*(.3+rnd()*.4);ell(c,x,y,S*.06,S*.04);c.fillStyle='#f0e8d0';c.fill();circ(c,x,y,S*.025);c.fillStyle='#c82020';c.fill()}},'Статуи');
inf('fissure','Огненная трещина',3,1,false,(c,S,rnd,p,W)=>{c.beginPath();c.moveTo(0,S*.5);for(let x=0;x<=W;x+=S*.25)c.lineTo(x,S*.5-S*(.08+rnd()*.12));for(let x=W;x>=0;x-=S*.25)c.lineTo(x,S*.5+S*(.08+rnd()*.12));c.closePath();c.fillStyle=lg(c,0,S*.3,0,S*.7,['#2a0a04','#ff9020','#2a0a04']);c.fill();ink(c,S,.02);c.stroke();glow(c,W/2,S/2,S*1.4,'rgba(255,90,20,.35)')},'Вода и лава','floor');
inf('sac-pit','Жертвенная яма',2,2,false,(c,S,rnd,p,W)=>{for(let i=0;i<10;i++){const a=i/10*PI*2;T.skull(c,S,W/2+Math.cos(a)*S*.85,W/2+Math.sin(a)*S*.85,.8)}circ(c,W/2,W/2,S*.7);c.fillStyle=rg(c,W/2,W/2,0,S*.7,['#ff6a10','#6e0a04','#000']);c.fill();ink(c,S);c.stroke()},'Ловушки','floor');
inf('demon-idol','Идол архидемона',2,2,true,(c,S,rnd,p,W)=>{const pts=[];for(let i=0;i<6;i++){const a=i/6*PI*2;pts.push([W/2+Math.cos(a)*W*.46,W/2+Math.sin(a)*W*.46])}poly(c,pts);c.fillStyle='#26252a';c.fill();ink(c,S);c.stroke();M.render&&0;c.save();c.translate(0,0);const fig=(x,y,k)=>{ell(c,x,y,S*.5*k,S*.3*k);c.fillStyle='#4a1410';c.fill();ink(c,S,.02);c.stroke();circ(c,x,y-S*.05,S*.22*k);c.fillStyle='#6e1e18';c.fill();c.stroke();[-1,1].forEach(s=>{c.beginPath();c.moveTo(x+s*S*.12,y-S*.2);c.quadraticCurveTo(x+s*S*.45,y-S*.5,x+s*S*.3,y-S*.75);c.lineWidth=S*.07;c.strokeStyle='#1a0808';c.stroke()})};fig(W/2,W/2,1.2);c.restore();c.fillStyle='#ff3a10';circ(c,W/2-S*.08,W/2-S*.1,S*.03);c.fill();circ(c,W/2+S*.08,W/2-S*.1,S*.03);c.fill();glow(c,W/2,W/2,S*1.1,'rgba(255,50,20,.25)')},'Статуи');
inf('burning-skulls','Горящие черепа',1,1,false,(c,S,rnd)=>{for(let i=0;i<4;i++){const x=S*(.25+rnd()*.5),y=S*(.25+rnd()*.5);T.skull(c,S,x,y,.9);flame(c,S,x,y-S*.08,1.2)}},'Свет');
inf('tormented-tree','Дерево страданий',2,2,true,(c,S,rnd,p,W)=>{c.fillStyle='rgba(60,10,8,.5)';blob(c,W/2,W/2,W*.45,rnd,11,.4);c.fill();const br=(x0,y0,a,l,w,d)=>{if(d<0)return;const x1=x0+Math.cos(a)*l,y1=y0+Math.sin(a)*l;c.strokeStyle='#1a0808';c.lineWidth=w;c.beginPath();c.moveTo(x0,y0);c.lineTo(x1,y1);c.stroke();if(d===0){T.skull(c,S,x1,y1,.5)}br(x1,y1,a-.5,l*.65,w*.6,d-1);br(x1,y1,a+.5,l*.65,w*.6,d-1)};for(let i=0;i<5;i++)br(W/2,W/2,i/5*PI*2,S*.35,S*.12,3)},'Природа','top');
// ---- небесное ----
const cel=(id,n,w,h,solid,f,cat,layer)=>add('cel-'+id,n,cat||'Культ',['небесное','храм','обитель ангелов'],w,h,solid,layer||'object',f);
cel('cloud','Облачный покров',2,2,false,(c,S,rnd,p,W)=>{for(let i=0;i<9;i++){circ(c,W*(.25+rnd()*.5),W*(.25+rnd()*.5),S*(.3+rnd()*.25));c.fillStyle=`rgba(255,255,255,${.35+rnd()*.3})`;c.fill()}},'Природа','floor');
cel('light-pillar','Столп света',1,1,false,(c,S)=>{glow(c,S/2,S/2,S*.9,'rgba(255,250,210,.6)');circ(c,S/2,S/2,S*.28);c.fillStyle=rg(c,S/2,S/2,0,S*.28,['#ffffff','rgba(255,240,180,.4)']);c.fill()},'Магия');
cel('feathers','Россыпь белых перьев',1,1,false,(c,S,rnd)=>{for(let i=0;i<8;i++){c.save();c.translate(S*(.15+rnd()*.7),S*(.15+rnd()*.7));c.rotate(rnd()*PI*2);c.beginPath();c.moveTo(0,-S*.09);c.quadraticCurveTo(S*.04,0,0,S*.09);c.quadraticCurveTo(-S*.04,0,0,-S*.09);c.fillStyle='#f8f6f0';c.fill();c.strokeStyle='rgba(150,150,160,.6)';c.lineWidth=S*.006;c.stroke();c.beginPath();c.moveTo(0,-S*.09);c.lineTo(0,S*.11);c.stroke();c.restore()}},'Декор','floor');
cel('mosaic','Звёздная мозаика пола',3,3,false,(c,S,rnd,p,W)=>{c.save();circ(c,W/2,W/2,W*.48);c.clip();for(let i=0;i<16;i++){c.beginPath();c.moveTo(W/2,W/2);c.arc(W/2,W/2,W*.48,i/16*PI*2,(i+1)/16*PI*2);c.closePath();c.fillStyle=i%2?'#f4f0e6':'#d8c890';c.fill()}c.restore();c.strokeStyle='#c49a3c';c.lineWidth=S*.04;circ(c,W/2,W/2,W*.48);c.stroke();c.beginPath();for(let i=0;i<16;i++){const a=i/16*PI*2,r=i%2?W*.15:W*.4;c.lineTo(W/2+Math.cos(a)*r,W/2+Math.sin(a)*r)}c.closePath();c.fillStyle='#d8b440';c.fill();c.stroke();circ(c,W/2,W/2,S*.2);c.fillStyle='#4a6fa8';c.fill();c.stroke()},'Декор','floor');
cel('chimes','Кристальные колокольчики',1,1,false,(c,S,rnd)=>{for(let i=0;i<7;i++){const a=i/7*PI*2;const x=S/2+Math.cos(a)*S*.25,y=S/2+Math.sin(a)*S*.25;poly(c,[[x,y-S*.06],[x+S*.03,y],[x,y+S*.06],[x-S*.03,y]]);c.fillStyle='rgba(220,240,255,.9)';c.fill();c.strokeStyle='#c49a3c';c.lineWidth=S*.008;c.stroke();c.beginPath();c.moveTo(S/2,S/2);c.lineTo(x,y);c.stroke()}glow(c,S/2,S/2,S*.5,'rgba(220,240,255,.4)')},'Декор','top');
cel('halo-fountain','Источник с нимбом',2,2,true,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,S*.9);c.fillStyle=lg(c,0,0,W,W,['#f4f0e6','#bdb8ae']);c.fill();ink(c,S);c.stroke();circ(c,W/2,W/2,S*.7);c.fillStyle=rg(c,W/2,W/2,0,S*.7,['#ffffff','#a0d0f0']);c.fill();c.strokeStyle='#f2da7a';c.lineWidth=S*.06;circ(c,W/2,W/2,S*.35);c.stroke();glow(c,W/2,W/2,S*1.2,'rgba(255,240,180,.4)')},'Вода и лава');
cel('golden-gate','Золотые врата',3,1,true,(c,S,rnd,p,W)=>{stoneBlock(c,S,0,S*.3,S*.3,S*.4,P.marble,rnd);stoneBlock(c,S,W-S*.3,S*.3,S*.3,S*.4,P.marble,rnd);c.strokeStyle='#d8b440';c.lineWidth=S*.05;for(let x=S*.45;x<W-S*.3;x+=S*.2){c.beginPath();c.moveTo(x,S*.4);c.lineTo(x,S*.6);c.stroke()}c.beginPath();c.moveTo(S*.3,S*.5);c.lineTo(W-S*.3,S*.5);c.stroke();circ(c,W/2,S*.5,S*.15);c.fillStyle='#f2da7a';c.fill();ink(c,S,.02);c.stroke();glow(c,W/2,S/2,S,'rgba(255,230,150,.3)')},'Двери и окна');
// ---- эльфы и фейвайлд ----
const elf=(id,n,th,w,h,solid,f,cat,layer)=>add('elf-'+id,n,cat||'Декор',th,w,h,solid,layer||'object',f);
elf('moonwell','Лунный колодец',['эльфы','фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{for(let i=0;i<14;i++){const a=i/14*PI*2;c.save();c.translate(W/2+Math.cos(a)*S*.78,W/2+Math.sin(a)*S*.78);c.rotate(a);stoneBlock(c,S,-S*.1,-S*.14,S*.2,S*.28,P.marble,rnd);c.restore()}circ(c,W/2,W/2,S*.65);c.fillStyle=rg(c,W/2,W/2,0,S*.65,['#ffffff','#a0c8f0','#1a2a5a']);c.fill();ink(c,S);c.stroke();c.fillStyle='#ffffff';circ(c,W/2+S*.15,W/2-S*.1,S*.15);c.fill();c.fillStyle='#a0c8f0';circ(c,W/2+S*.2,W/2-S*.14,S*.13);c.fill();glow(c,W/2,W/2,S*1.2,'rgba(200,220,255,.4)')},'Вода и лава');
elf('platform','Помост на дереве',['эльфы','лес'],3,3,false,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,W*.47);c.save();circ(c,W/2,W/2,W*.46);c.clip();for(let i=0;i<14;i++)wood(c,S,0,i*W/14,W,W/14,P.lwood,rnd,'h',1);c.restore();ink(c,S);circ(c,W/2,W/2,W*.46);c.stroke();circ(c,W/2,W/2,S*.4);c.fillStyle=rg(c,W/2,W/2,0,S*.4,['#9a6e44','#45301e']);c.fill();c.stroke();c.strokeStyle='#8a6a3a';c.lineWidth=S*.05;circ(c,W/2,W/2,W*.44);c.stroke()},'Мебель','floor');
elf('pavilion','Беседка из листвы',['эльфы','сад'],3,3,false,(c,S,rnd,p,W)=>{for(let i=0;i<6;i++){const a=i/6*PI*2;circ(c,W/2+Math.cos(a)*W*.4,W/2+Math.sin(a)*W*.4,S*.12);c.fillStyle='#e8e0d0';c.fill();ink(c,S,.02);c.stroke()}c.save();c.globalAlpha=.85;for(let i=0;i<30;i++){const a=rnd()*PI*2,d=rnd()*W*.45;ell(c,W/2+Math.cos(a)*d,W/2+Math.sin(a)*d,S*.25,S*.12,a);c.fillStyle=['#5a8a3a','#7aaa4a','#9ac060'][i%3];c.fill()}c.restore();for(let i=0;i<8;i++){circ(c,W*(.2+rnd()*.6),W*(.2+rnd()*.6),S*.05);c.fillStyle='#f0e0ff';c.fill()}},'Природа','top');
elf('lantern-tree','Дерево-светильник',['эльфы','фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{M.render(c,'md2-tree-эльфийский-ясень-2',S,{seed:'lt'});for(let i=0;i<9;i++){const x=W*(.2+rnd()*.6),y=W*(.2+rnd()*.6);glow(c,x,y,S*.3,'rgba(255,240,170,.6)');circ(c,x,y,S*.05);c.fillStyle='#fff8d0';c.fill()}},'Свет','top');
elf('root-bench','Скамья из корней',['эльфы','лес','фейвайлд'],2,1,false,(c,S,rnd,p,W)=>{c.strokeStyle='#5a3c22';for(let i=0;i<6;i++){c.lineWidth=S*(.06+rnd()*.04);c.beginPath();c.moveTo(0,S*(.3+rnd()*.4));c.bezierCurveTo(W*.3,S*(.2+rnd()*.6),W*.7,S*(.2+rnd()*.6),W,S*(.3+rnd()*.4));c.stroke()}c.fillStyle='rgba(90,128,50,.8)';for(let i=0;i<5;i++){blob(c,rnd()*W,S*(.3+rnd()*.4),S*.08,rnd,6,.5);c.fill()}},'Мебель');
elf('flower-arch','Цветочная арка',['эльфы','сад','фейвайлд'],3,1,false,(c,S,rnd,p,W)=>{c.strokeStyle='#3a6a20';c.lineWidth=S*.08;c.beginPath();c.moveTo(S*.15,S*.5);c.quadraticCurveTo(W/2,S*.2,W-S*.15,S*.5);c.stroke();for(let i=0;i<14;i++){const t=i/13,x=S*.15+t*(W-S*.3),y=S*.5-Math.sin(t*PI)*S*.15;circ(c,x+(rnd()-.5)*S*.1,y+(rnd()-.5)*S*.1,S*.06);c.fillStyle=['#f0a0d0','#f4f0e6','#c080f0'][i%3];c.fill()}},'Природа','top');
elf('toadstool-table','Стол-поганка с табуретами-грибами',['фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{const shr=(x,y,r)=>{shadow(c,S,()=>{circ(c,x,y,r);c.fillStyle='#000';c.fill()},.2);circ(c,x,y,r);c.fillStyle=rg(c,x-r*.3,y-r*.3,0,r,['#ff7a6a','#a01e18']);c.fill();ink(c,S,.02);c.stroke();c.fillStyle='#f4f0e6';for(let i=0;i<5;i++){circ(c,x+Math.cos(i*1.3)*r*.55,y+Math.sin(i*1.3)*r*.55,r*.13);c.fill()}};shr(W/2,W/2,S*.55);[[.25,.25],[1.75,.3],[.3,1.75],[1.7,1.7]].forEach(q=>shr(S*q[0],S*q[1],S*.2));T.mug(c,S,W/2-S*.15,W/2);T.mug(c,S,W/2+S*.15,W/2+S*.1)},'Мебель');
elf('dewdrop-pool','Пруд-росинка',['фейвайлд'],1,1,false,(c,S)=>{circ(c,S/2,S/2,S*.35);c.fillStyle=rg(c,S*.4,S*.4,0,S*.4,['#ffffff','#b0e8ff','#4a8ad8']);c.fill();c.strokeStyle='rgba(255,255,255,.8)';c.lineWidth=S*.02;c.stroke();circ(c,S*.4,S*.38,S*.08);c.fillStyle='rgba(255,255,255,.9)';c.fill()},'Вода и лава','floor');
elf('acorn-house','Дом-жёлудь',['фейвайлд','лес'],2,2,true,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,S*.85);c.fillStyle=rg(c,W*.42,W*.42,0,S*.9,['#c8944a','#8a5a2a','#4a2a10']);c.fill();ink(c,S);c.stroke();c.save();circ(c,W/2,W/2,S*.55);c.clip();c.fillStyle='#5a3c22';c.fillRect(0,0,W,W);c.strokeStyle='#3a2414';c.lineWidth=S*.02;for(let i=-10;i<10;i++){c.beginPath();c.moveTo(W/2+i*S*.1,0);c.lineTo(W/2+i*S*.1+W,W);c.moveTo(W/2+i*S*.1,0);c.lineTo(W/2+i*S*.1-W,W);c.stroke()}c.restore();circ(c,W/2,W/2,S*.08);c.fillStyle='#3a2414';c.fill()},'Мебель');
elf('butterflies','Светящиеся бабочки',['фейвайлд','сад'],1,1,false,(c,S,rnd)=>{for(let i=0;i<5;i++){const x=S*(.2+rnd()*.6),y=S*(.2+rnd()*.6),col=['#ff9ae8','#9ae8ff','#fff09a'][i%3];glow(c,x,y,S*.12,'rgba(255,255,220,.5)');c.fillStyle=col;ell(c,x-S*.03,y,S*.03,S*.045,-.4);c.fill();ell(c,x+S*.03,y,S*.03,S*.045,.4);c.fill()}},'Природа','top');
elf('tea-set','Зачарованный чайный сервиз',['фейвайлд','особняк'],1,1,false,(c,S,rnd)=>{circ(c,S/2,S/2,S*.4);c.fillStyle='#e8e0d0';c.fill();ink(c,S,.015);c.stroke();circ(c,S/2,S/2,S*.12);c.fillStyle='#f4f0e6';c.fill();c.stroke();for(let i=0;i<4;i++){const a=i/4*PI*2+.4;circ(c,S/2+Math.cos(a)*S*.26,S/2+Math.sin(a)*S*.26,S*.06);c.fillStyle='#f8f0ff';c.fill();c.stroke();circ(c,S/2+Math.cos(a)*S*.26,S/2+Math.sin(a)*S*.26,S*.04);c.fillStyle='#a8643a';c.fill()}glow(c,S/2,S/2,S*.5,'rgba(255,180,240,.25)')},'Еда');
