const snow=(id,n,w,h,solid,f,cat,layer)=>add('snow-'+id,n,cat||'Природа',['снег','север','ледник'],w,h,solid,layer||'object',f);
snow('ice-wall','Стена из ледяных блоков',3,1,true,(c,S,rnd,p,W)=>{for(let i=0;i<6;i++)for(let j=0;j<2;j++){rr(c,S*(i*.5+(j%2)*.25)-S*.1,S*(.15+j*.35),S*.48,S*.33,S*.04);c.fillStyle=lg(c,0,0,S,S,['#e8f8ff','#8ab8d0']);c.fill();c.strokeStyle='rgba(60,100,130,.6)';c.lineWidth=S*.015;c.stroke()}},'Обломки');
snow('igloo','Иглу',3,3,true,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,W*.42);c.fillStyle=rg(c,W*.42,W*.42,0,W*.45,['#ffffff','#c8dce8','#8aa8c0']);c.fill();ink(c,S);c.stroke();c.strokeStyle='rgba(100,130,160,.5)';c.lineWidth=S*.015;for(let r=.12;r<.42;r+=.08){circ(c,W/2,W/2,W*r);c.stroke()}for(let i=0;i<16;i++){const a=i/16*PI*2;c.beginPath();c.moveTo(W/2+Math.cos(a)*W*.12,W/2+Math.sin(a)*W*.12);c.lineTo(W/2+Math.cos(a)*W*.42,W/2+Math.sin(a)*W*.42);c.stroke()}rr(c,W/2-S*.3,W*.85,S*.6,S*.45,S*.15);c.fillStyle='#d8e8f0';c.fill();ink(c,S,.02);c.stroke();c.fillStyle='#1a2a3a';rr(c,W/2-S*.18,W*.9,S*.36,S*.35,S*.1);c.fill()},'Мебель');
snow('sled','Сани с поклажей',1,2,true,(c,S,rnd,p,W,H)=>{c.strokeStyle='#5c4129';c.lineWidth=S*.04;[S*.2,S*.8].forEach(x=>{c.beginPath();c.moveTo(x,H-S*.1);c.lineTo(x,S*.3);c.quadraticCurveTo(x,S*.05,S/2,S*.05);c.stroke()});wood(c,S,S*.2,S*.4,S*.6,S*1.4,P.lwood,rnd,'h',5);M.render&&0;c.save();c.translate(S*.3,S*.6);M.render(c,'md1-crate-small',S*.8,{seed:'sl'});c.restore();c.save();c.translate(S*.1,S*1.1);M.render(c,'md1-sack',S*.8,{seed:'sl2'});c.restore()},'Механизмы');
snow('snowman','Снеговик',1,1,true,(c,S)=>{[[.5,.6,.3],[.5,.42,.2]].forEach(q=>{circ(c,S*q[0],S*q[1],S*q[2]);c.fillStyle=rg(c,S*q[0]-S*.05,S*q[1]-S*.05,0,S*q[2],['#ffffff','#c8dce8']);c.fill();ink(c,S,.02);c.stroke()});c.fillStyle='#e8782a';poly(c,[[S*.5,S*.4],[S*.5,S*.48],[S*.62,S*.44]]);c.fill();c.fillStyle='#22170e';circ(c,S*.45,S*.38,S*.02);c.fill();circ(c,S*.55,S*.38,S*.02);c.fill()},'Декор');
snow('ice-throne','Ледяной трон',2,2,true,(c,S,rnd,p,W)=>{const CR=['#7ab8d8','#2a5a7a','#f0ffff'];for(let i=0;i<9;i++){const a=PI+i/8*PI;c.save();c.translate(W/2,W*.6);c.rotate(a);poly(c,[[0,-S*.08],[S*.95,0],[0,S*.08]]);c.fillStyle=lg(c,0,0,S,0,[CR[2],CR[0]]);c.fill();ink(c,S,.012);c.stroke();c.restore()}rr(c,W/2-S*.45,W*.45,S*.9,S*.8,S*.1);c.fillStyle=lg(c,0,0,W,W,['#e8f8ff','#7ab8d8']);c.fill();ink(c,S);c.stroke();glow(c,W/2,W/2,S*1.2,'rgba(200,240,255,.3)')},'Мебель');
snow('fur-pile','Груда шкур',1,1,false,(c,S,rnd)=>{for(let i=0;i<4;i++){c.save();c.translate(S/2,S/2);c.rotate(rnd()*PI);blob(c,0,0,S*.35,rnd,9,.4);c.fillStyle=['#6a5236','#a8a8a0','#3a2a1a','#d8d8d0'][i];c.fill();ink(c,S,.015);c.stroke();c.restore()}},'Ковры');
snow('frozen-pond','Замёрзший пруд',3,3,false,(c,S,rnd,p,W)=>{blob(c,W/2,W/2,W*.44,rnd,12,.25);c.fillStyle=rg(c,W*.4,W*.4,0,W*.5,['#e8f8ff','#a0c8dc','#6a98b0']);c.fill();ink(c,S,.02);c.stroke();c.strokeStyle='rgba(255,255,255,.8)';c.lineWidth=S*.015;for(let i=0;i<6;i++){let x=W*(.3+rnd()*.4),y=W*(.3+rnd()*.4);c.beginPath();c.moveTo(x,y);for(let k=0;k<4;k++){x+=(rnd()-.5)*S*.6;y+=(rnd()-.5)*S*.6;c.lineTo(x,y)}c.stroke()}c.fillStyle='#1a3a4a';blob(c,W*.65,W*.6,S*.2,rnd,8,.4);c.fill()},'Вода и лава','floor');
snow('ski-rack','Лыжи и снегоступы',1,1,false,(c,S)=>{for(let i=0;i<3;i++){rr(c,S*(.18+i*.12),S*.08,S*.07,S*.84,S*.03);c.fillStyle='#8a6239';c.fill();ink(c,S,.012);c.stroke()}ell(c,S*.75,S*.5,S*.14,S*.25);c.strokeStyle='#5c4129';c.lineWidth=S*.025;c.stroke();for(let i=0;i<4;i++){c.beginPath();c.moveTo(S*.62,S*(.35+i*.1));c.lineTo(S*.88,S*(.35+i*.1));c.lineWidth=S*.008;c.stroke()}},'Декор');
// ---- полы (участки покрытий) ----
const floor=(id,n,th,f)=>add('floor-'+id,n,'Декор',th,2,2,false,'floor',(c,S,rnd,p,W)=>{c.save();c.beginPath();c.rect(0,0,W,W);c.clip();f(c,S,rnd,W);c.restore()});
floor('planks','Пол: дощатый',['таверна','дом','корабль'],(c,S,rnd,W)=>{for(let i=0;i<8;i++){const off=(i%2)*S*.7;wood(c,S,-off,i*W/8,S*1.4,W/8,P.wood,rnd,'h',1);wood(c,S,S*1.4-off,i*W/8,S*1.4,W/8,P.wood,rnd,'h',1)}});
floor('flagstone','Пол: каменные плиты',['замок','подземелье','храм'],(c,S,rnd,W)=>{for(let i=0;i<4;i++)for(let j=0;j<4;j++)stoneBlock(c,S,i*S*.5+S*.01,j*S*.5+S*.01,S*.48,S*.48,rnd()<.3?P.dstone:P.stone,rnd)});
floor('cobble','Мостовая: булыжник',['город','улица'],(c,S,rnd,W)=>{c.fillStyle='#3a3530';c.fillRect(0,0,W,W);for(let i=0;i<7;i++)for(let j=0;j<7;j++){blob(c,S*(.15+i*.29+(j%2)*.14),S*(.15+j*.29),S*.13,rnd,7,.3);c.fillStyle=rg(c,S*(.12+i*.29),S*(.12+j*.29),0,S*.15,['#a8a399','#6a6761']);c.fill();ink(c,S,.012);c.stroke()}});
floor('marble-check','Пол: мраморная шахматка',['дворец','храм','особняк'],(c,S,rnd,W)=>{for(let i=0;i<4;i++)for(let j=0;j<4;j++){c.fillStyle=(i+j)%2?'#2a2a30':'#e8e3d8';c.fillRect(i*S*.5,j*S*.5,S*.5,S*.5);c.strokeStyle=(i+j)%2?'rgba(120,120,140,.3)':'rgba(150,140,120,.35)';c.lineWidth=S*.008;c.beginPath();c.moveTo(i*S*.5+rnd()*S*.5,j*S*.5);c.quadraticCurveTo(i*S*.5+rnd()*S*.5,j*S*.5+S*.25,i*S*.5+rnd()*S*.5,j*S*.5+S*.5);c.stroke()}c.strokeStyle='rgba(0,0,0,.3)';c.lineWidth=S*.01;for(let i=0;i<=4;i++){c.beginPath();c.moveTo(i*S*.5,0);c.lineTo(i*S*.5,W);c.moveTo(0,i*S*.5);c.lineTo(W,i*S*.5);c.stroke()}});
floor('mosaic','Пол: мозаика',['храм','термы','дворец'],(c,S,rnd,W)=>{const k=S*.1;for(let x=0;x<W;x+=k)for(let y=0;y<W;y+=k){const d=Math.hypot(x-W/2,y-W/2)/S;c.fillStyle=['#e8e0c8','#2f4f86','#b8463a','#d8b440','#e8e0c8'][Math.floor(d*3)%5];c.fillRect(x+S*.005,y+S*.005,k-S*.01,k-S*.01)}});
floor('dirt','Пол: утоптанная земля',['хижина','лагерь','шахта'],(c,S,rnd,W)=>{c.fillStyle='#6a5236';c.fillRect(0,0,W,W);for(let i=0;i<120;i++){circ(c,rnd()*W,rnd()*W,S*(.01+rnd()*.03));c.fillStyle=rnd()<.5?'rgba(40,28,15,.4)':'rgba(140,110,70,.4)';c.fill()}});
floor('herringbone','Пол: паркет ёлочкой',['особняк','дворец'],(c,S,rnd,W)=>{c.fillStyle=P.wood[1];c.fillRect(0,0,W,W);const L=S*.35,w=S*.12;for(let x=-L;x<W+L;x+=w*2)for(let y=-L;y<W+L;y+=L){[[x,y,PI/4],[x+w,y,-PI/4]].forEach(q=>{c.save();c.translate(q[0],q[1]);c.rotate(q[2]);c.fillStyle=P.wood[1+((Math.abs(x+y)/w|0)%3)];c.fillRect(0,0,L,w);c.strokeStyle='rgba(20,12,6,.5)';c.lineWidth=S*.008;c.strokeRect(0,0,L,w);c.restore()})}});
floor('grate','Пол: металлическая решётка',['канализация','тюрьма','мастерская'],(c,S,rnd,W)=>{c.fillStyle='#0a0806';c.fillRect(0,0,W,W);c.strokeStyle='#45484d';c.lineWidth=S*.04;for(let i=0;i<=10;i++){c.beginPath();c.moveTo(i*W/10,0);c.lineTo(i*W/10,W);c.moveTo(0,i*W/10);c.lineTo(W,i*W/10);c.stroke()}});
floor('straw','Пол: солома',['конюшня','амбар','тюрьма'],(c,S,rnd,W)=>{c.fillStyle='#8a7040';c.fillRect(0,0,W,W);c.lineWidth=S*.012;for(let i=0;i<300;i++){const x=rnd()*W,y=rnd()*W,a=rnd()*PI;c.strokeStyle=['#d8c070','#b0943a','#e8d890'][i%3];c.beginPath();c.moveTo(x,y);c.lineTo(x+Math.cos(a)*S*.15,y+Math.sin(a)*S*.15);c.stroke()}});
floor('cave','Пол: неровный камень пещеры',['пещера','подземье'],(c,S,rnd,W)=>{c.fillStyle='#4a4540';c.fillRect(0,0,W,W);for(let i=0;i<14;i++){blob(c,rnd()*W,rnd()*W,S*(.2+rnd()*.3),rnd,8,.5);c.fillStyle=`rgba(${rnd()<.5?'0,0,0':'160,150,140'},.15)`;c.fill()}M.cracks(c,S,0,0,W,W,rnd,5)});
// ---- стены и проёмы ----
const wseg=(id,n,th,w,h,f,cat)=>add('wallseg-'+id,n,cat||'Обломки',th,w,h,true,'object',f);
wseg('stone','Каменная стена (отрезок)',['подземелье','замок'],3,1,(c,S,rnd,p,W)=>{for(let i=0;i<6;i++)for(let j=0;j<2;j++)stoneBlock(c,S,S*(i*.5+(j%2)*.25)-S*.25,S*(.25+j*.25),S*.5,S*.25,P.stone,rnd)});
wseg('stone-corner','Угол каменной стены',['подземелье','замок'],2,2,(c,S,rnd,p,W)=>{for(let i=0;i<4;i++)for(let j=0;j<2;j++)stoneBlock(c,S,S*i*.5,S*(.25+j*.25),S*.5,S*.25,P.stone,rnd);for(let i=1;i<4;i++)for(let j=0;j<2;j++)stoneBlock(c,S,S*(.25+j*.25),S*(i*.5+.25),S*.25,S*.5,P.stone,rnd)});
wseg('stone-broken','Обрушенная стена',['руины'],3,1,(c,S,rnd,p,W)=>{for(let i=0;i<6;i++){const h=i>1&&i<4?1:2;for(let j=0;j<h;j++)stoneBlock(c,S,S*i*.5,S*(.25+j*.25),S*.5,S*.25,P.stone,rnd)}for(let i=0;i<8;i++){const s=S*(.1+rnd()*.15);stoneBlock(c,S,S*(1+rnd()),S*(.55+rnd()*.35),s,s*.8,P.stone,rnd)}});
wseg('brick','Кирпичная стена',['город','дом'],3,1,(c,S,rnd,p,W)=>{for(let i=0;i<13;i++)for(let j=0;j<3;j++){rr(c,S*(i*.25+(j%2)*.12)-S*.12,S*(.3+j*.14),S*.24,S*.13,S*.01);c.fillStyle=['#8a3a2a','#a84a32','#6e2e20'][(i+j)%3];c.fill();c.strokeStyle='#c8b8a0';c.lineWidth=S*.01;c.stroke()}});
wseg('timber','Бревенчатая стена',['деревня','лес','север'],3,1,(c,S,rnd,p,W)=>{for(let j=0;j<2;j++){rr(c,0,S*(.3+j*.2),W,S*.2,S*.1);c.fillStyle=lg(c,0,S*(.3+j*.2),0,S*(.5+j*.2),['#9a6e44','#5a3c22']);c.fill();ink(c,S,.015);c.stroke()}});
wseg('bars','Решётчатая стена камеры',['тюрьма'],3,1,(c,S,rnd,p,W)=>{stoneBlock(c,S,0,S*.25,S*.3,S*.5,P.dstone,rnd);stoneBlock(c,S,W-S*.3,S*.25,S*.3,S*.5,P.dstone,rnd);c.fillStyle='#1e2024';c.fillRect(S*.3,S*.36,W-S*.6,S*.07);c.fillRect(S*.3,S*.57,W-S*.6,S*.07);for(let x=S*.42;x<W-S*.3;x+=S*.17){circ(c,x,S/2,S*.065);c.fillStyle=rg(c,x-S*.02,S*.48,0,S*.07,['#9aa0a8','#3a3d42']);c.fill();c.strokeStyle='#0a0a0c';c.lineWidth=S*.015;c.stroke()}c.fillStyle='rgba(120,60,30,.5)';for(let i=0;i<5;i++){circ(c,S*.4+rnd()*(W-S*.8),S*(.4+rnd()*.2),S*.025);c.fill()}});
wseg('palisade-gate','Ворота частокола',['лагерь','деревня','крепость'],3,1,(c,S,rnd,p,W)=>{for(let x=S*.1;x<S*.7;x+=S*.2){circ(c,x,S/2,S*.11);c.fillStyle='#7a5432';c.fill();ink(c,S,.015);c.stroke()}for(let x=W-S*.1;x>W-S*.7;x-=S*.2){circ(c,x,S/2,S*.11);c.fillStyle='#7a5432';c.fill();ink(c,S,.015);c.stroke()}wood(c,S,S*.7,S*.4,W-S*1.4,S*.2,P.wood,rnd,'v',6)},'Двери и окна');
// ---- лестницы и люки ----
const st=(id,n,th,w,h,f,solid)=>add('stairs-'+id,n,'Двери и окна',th,w,h,!!solid,'floor',f);
st('down','Лестница вниз',['подземелье','замок'],1,2,(c,S,rnd,p,W,H)=>{for(let i=0;i<8;i++){const t=i/8;c.fillStyle=`rgb(${150-t*130},${145-t*125},${135-t*120})`;c.fillRect(S*.05,i*H/8,S*.9,H/8);c.strokeStyle='rgba(0,0,0,.5)';c.lineWidth=S*.015;c.strokeRect(S*.05,i*H/8,S*.9,H/8)}ink(c,S);c.strokeRect(S*.05,0,S*.9,H);c.fillStyle='rgba(255,255,255,.7)';poly(c,[[S/2,H*.85],[S*.4,H*.7],[S*.6,H*.7]]);c.fill()});
st('up','Лестница вверх',['подземелье','замок','башня'],1,2,(c,S,rnd,p,W,H)=>{for(let i=0;i<8;i++){const t=1-i/8;c.fillStyle=`rgb(${200-t*80},${195-t*80},${185-t*80})`;c.fillRect(S*.05,i*H/8,S*.9,H/8);c.strokeStyle='rgba(0,0,0,.45)';c.lineWidth=S*.015;c.strokeRect(S*.05,i*H/8,S*.9,H/8)}ink(c,S);c.strokeRect(S*.05,0,S*.9,H);c.fillStyle='rgba(30,20,10,.7)';poly(c,[[S/2,H*.15],[S*.4,H*.3],[S*.6,H*.3]]);c.fill()});
st('wide','Широкая парадная лестница',['дворец','замок','храм'],3,2,(c,S,rnd,p,W,H)=>{for(let i=0;i<8;i++){stoneBlock(c,S,S*.02,i*H/8,W-S*.04,H/8,i%2?P.marble:P.stone,rnd)}c.fillStyle='#6e1e18';c.fillRect(W/2-S*.4,0,S*.8,H)});
st('spiral','Винтовая лестница',['башня','замок','маяк'],2,2,(c,S,rnd,p,W)=>{circ(c,W/2,W/2,W*.46);c.fillStyle='#3a3940';c.fill();ink(c,S);c.stroke();for(let i=0;i<12;i++){const a0=i/12*PI*2,a1=(i+1)/12*PI*2;const t=i/12;c.beginPath();c.moveTo(W/2+Math.cos(a0)*S*.2,W/2+Math.sin(a0)*S*.2);c.arc(W/2,W/2,W*.44,a0,a1);c.lineTo(W/2+Math.cos(a1)*S*.2,W/2+Math.sin(a1)*S*.2);c.closePath();c.fillStyle=`rgb(${180-t*120},${175-t*115},${165-t*110})`;c.fill();c.strokeStyle='rgba(0,0,0,.5)';c.lineWidth=S*.015;c.stroke()}circ(c,W/2,W/2,S*.2);c.fillStyle='#6a6761';c.fill();ink(c,S,.02);c.stroke()},true);
st('ladder','Приставная лестница',['любая'],1,1,(c,S,rnd)=>{c.fillStyle=P.wood[1];c.fillRect(S*.25,S*.02,S*.08,S*.96);c.fillRect(S*.67,S*.02,S*.08,S*.96);for(let i=0;i<5;i++)c.fillRect(S*.25,S*(.1+i*.2),S*.5,S*.06);ink(c,S,.012);c.strokeRect(S*.25,S*.02,S*.5,S*.96)});
st('trapdoor','Люк в полу',['таверна','дом','склад'],1,1,(c,S,rnd)=>{wood(c,S,S*.1,S*.1,S*.8,S*.8,P.dwood,rnd,'v',4);c.fillStyle='#2b2d30';c.fillRect(S*.1,S*.25,S*.8,S*.05);c.fillRect(S*.1,S*.7,S*.8,S*.05);c.strokeStyle='#63676d';c.lineWidth=S*.025;circ(c,S/2,S*.5,S*.07);c.stroke()});
st('trapdoor-open','Открытый люк',['таверна','склад','подземелье'],1,1,(c,S,rnd)=>{c.fillStyle='#000';c.fillRect(S*.1,S*.1,S*.8,S*.8);for(let i=0;i<4;i++){c.fillStyle=P.wood[1];c.fillRect(S*.35,S*(.2+i*.18),S*.3,S*.04)}c.save();c.translate(S*.1,S*.1);c.rotate(-.3);c.globalAlpha=.9;wood(c,S,0,-S*.2,S*.8,S*.2,P.dwood,rnd,'v',4);c.restore()});
st('rope-ladder','Верёвочная лестница',['корабль','джунгли','башня'],1,1,(c,S)=>{c.strokeStyle='#a8946e';c.lineWidth=S*.03;c.beginPath();c.moveTo(S*.3,0);c.lineTo(S*.32,S);c.moveTo(S*.7,0);c.lineTo(S*.68,S);c.stroke();c.fillStyle=P.wood[2];for(let i=0;i<5;i++)c.fillRect(S*.3,S*(.1+i*.2),S*.4,S*.05)});
st('pit-descent','Провал с верёвкой',['пещера','шахта'],2,2,(c,S,rnd,p,W)=>{blob(c,W/2,W/2,W*.42,rnd,11,.3);c.fillStyle=rg(c,W/2,W/2,0,W*.45,['#000','#000','#2a2420']);c.fill();ink(c,S);c.stroke();c.strokeStyle='#a8946e';c.lineWidth=S*.04;c.beginPath();c.moveTo(W*.1,W*.1);c.quadraticCurveTo(W*.4,W*.3,W*.5,W*.55);c.stroke();circ(c,W*.1,W*.1,S*.1);c.fillStyle='#45484d';c.fill()});
